function ensureBalanceForRows(rows){const totals=new Map();for(const r of rows){const id=r.course_id||r.courseId,minutes=Number(r.deduct_minutes??r.minutes);if(!id||!Number.isInteger(minutes)||minutes<0)throw Error('คอร์สหรือระยะเวลาไม่ถูกต้อง');if(!isHourly(byId('Courses',id)))totals.set(id,(totals.get(id)||0)+minutes);}for(const [id,needed] of totals){if(balance(id)<needed)throw Error('ชั่วโมงของ '+studentName(byId('Courses',id)?.student_id)+' ไม่พอ: ต้องตัด '+nice(needed)+' แต่คงเหลือ '+nice(balance(id)));}}
