function buildApproval(ids){
  const unique=[...new Set(ids)],sessions=[],aa=[],totals=new Map();if(!unique.length)throw Error('กรุณาเลือกคาบเรียนที่ต้องการอนุมัติ');
  for(const id of unique){const s=byId('Sessions',id);if(!s||s.status!=='pending')throw Error('คาบที่เลือกไม่ได้อยู่ในสถานะรออนุมัติ กรุณารีเฟรชก่อน');
    if(!dateValid(s.date))throw Error('คาบที่เลือกยังไม่มีวันที่เรียนที่ถูกต้อง จึงไม่สามารถอนุมัติได้: '+(s.source_file||id));
    const at=all('Attendance').filter(a=>a.session_id===id);if(!at.length)throw Error('คาบ '+s.date+' ไม่มีผู้เรียน');sessions.push(s);
    for(const a of at){if(byId('Students',a.student_id)?.status!=='active')throw Error('นักเรียนไม่พร้อมใช้งาน: '+studentName(a.student_id));
      const c=byId('Courses',a.course_id);if(!c||!['active','held'].includes(c.status)||c.student_id!==a.student_id)throw Error('คอร์สไม่เปิดใช้งาน: '+studentName(a.student_id));
      const minutes=Number(a.deduct_minutes);if(!Number.isInteger(minutes)||minutes<0||minutes>720)throw Error('ชั่วโมงผิดปกติ: '+studentName(a.student_id));
      if(!isHourly(c))totals.set(a.course_id,(totals.get(a.course_id)||0)+minutes);aa.push(a);
    }
  }
  for(const [cid,required] of totals){if(balance(cid)<required)throw Error('ชั่วโมงของ '+studentName(byId('Courses',cid)?.student_id)+' ไม่พอ ต้องใช้ '+nice(required)+' เหลือ '+nice(balance(cid)));}
  return {sessions,aa};
}
function previewApproval(ids){
  const {sessions,aa}=buildApproval(ids),sessionMap=new Map(sessions.map(s=>[s.id,s]));
  const rows=aa.map(a=>{const s=sessionMap.get(a.session_id);return {student:studentName(a.student_id),source:s.source_file||'Manual',date:s.date,course:courseTitle(a.course_id),courseId:a.course_id,classLabel:s.group_id?byId('Groups',s.group_id)?.name||'เรียนกลุ่ม':'เรียนเดี่ยว',actual:a.actual_minutes,minutes:a.deduct_minutes,timeRange:s.start_time+'–'+s.end_time};});
  showSaveSummary('อนุมัติ '+sessions.length+' คาบเรียน','approve',rows,()=>approveSessions(sessions.map(s=>s.id)),'แพ็กเกจตัดชั่วโมง ส่วนรายชั่วโมงสร้างยอดรอชำระโดยยังไม่ถือว่าจ่ายเงินแล้ว');
}

function init(){store=new DemoStore();const back=document.createElement('div');back.className='mobile-backdrop';back.id='mobile-backdrop';document.body.appendChild(back);document.addEventListener('click',onClick);document.addEventListener('submit',onSubmit);document.addEventListener('change',onChange);document.addEventListener('input',onInput);document.addEventListener('dragenter',onFileDrag);document.addEventListener('dragover',onFileDrag);document.addEventListener('dragleave',onFileDrag);document.addEventListener('drop',onFileDrag);$('#menu-toggle').onclick=()=>toggleMenu(true);back.onclick=()=>toggleMenu(false);$('#refresh-btn').onclick=()=>{if(state.mode==='needs_login'){googleLogin();return;}if(state.mode==='setup_required'){openConnection();return;}reload().then(()=>toast('อัปเดตข้อมูลแล้ว')).catch(notice);};$('#connect-side').onclick=openConnection;$('#account-btn').onclick=openConnection;
  document.querySelectorAll('.nav-item, .nav-group-toggle').forEach(n=>{n.title=n.querySelector('.nav-label')?.textContent||'';});
  $('#sidebar-collapse')?.addEventListener('click',toggleSidebarCollapsed);
  $('#global-search-btn')?.addEventListener('click',openGlobalSearch);
  $('#header-quick')?.addEventListener('click',()=>go('manual'));
  $('#theme-switch')?.addEventListener('click',toggleTheme);
  $('#mobile-more-btn')?.addEventListener('click',()=>toggleMenu(true));
  if(safeStorage('local','get','awtutor_sidebar_collapsed_v2')==='true')document.body.classList.add('sidebar-collapsed');
  if(safeStorage('local','get','awtutor_ui_theme_v2')==='dark'){document.body.classList.add('theme-dark');$('#theme-switch')?.setAttribute('aria-pressed','true');}
  document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openGlobalSearch();}if(e.key==='Escape'&&$('#overlay')){closeModal();}else if(e.key==='Escape'&&$('#sidebar')?.classList.contains('open')){toggleMenu(false);}});
if(liveConfigured){state.mode='needs_login';render();restoreGoogleSession().catch(notice);}else{state.mode='setup_required';render();}}
function openGlobalSearch(){
  modal('ค้นหาทั่วระบบ',`<div class="global-search-dialog"><div class="global-search-input-wrap"><span aria-hidden="true">⌕</span><input id="global-search-input" type="search" autocomplete="off" placeholder="ค้นหาชื่อนักเรียน โรงเรียน คอร์ส หรือกลุ่ม…" aria-label="ค้นหาทั่วระบบ"><kbd>ESC</kbd></div><div id="global-search-results" class="global-search-results"></div><p class="helper">ค้นหาทั้งนักเรียน คอร์ส และกลุ่มเรียน · เลือกรายการเพื่อเปิดหน้าที่เกี่ยวข้อง</p></div>`);
  updateGlobalSearchResults('');$('#global-search-input')?.focus();
}
function updateGlobalSearchResults(text){
  const el=$('#global-search-results');if(!el)return;
  const q=norm(text||'');
  const matches=all('Students').filter(s=>s.status!=='deleted'&&norm([s.name,s.full_name,s.school,s.grade_level,s.email].join(' ')).includes(q)).slice(0,7).map(s=>({kind:'นักเรียน',title:s.name,desc:[s.school,s.grade_level].filter(Boolean).join(' · '),act:'search-student',id:s.id}));
  const courses=all('Courses').filter(c=>c.status==='active'&&norm([c.title,studentName(c.student_id)].join(' ')).includes(q)).slice(0,5).map(c=>({kind:'คอร์ส',title:c.title,desc:studentName(c.student_id),act:'search-student',id:c.student_id}));
  const groupsFound=all('Groups').filter(g=>norm(g.name).includes(q)).slice(0,5).map(g=>({kind:'กลุ่ม',title:g.name,desc:membersOf(g.id).length+' สมาชิก',act:'search-group',id:g.id}));
  const items=[...matches,...courses,...groupsFound].slice(0,14);
  el.innerHTML=items.length?items.map(x=>`<button type="button" class="global-search-result" data-action="${x.act}" data-id="${esc(x.id)}"><span class="search-result-kind">${x.kind}</span><span class="search-result-body"><strong>${esc(x.title)}</strong><small>${esc(x.desc||'')}</small></span><span aria-hidden="true">↗</span></button>`).join(''):'<div class="empty">ไม่พบข้อมูลที่ตรงกับคำค้นหา</div>';
}
// v2.3.1 — one compact navigation tree for all existing pages.
let lastNavigationView='';
function groupForView(view){const item=[...document.querySelectorAll('#nav .nav-subitem')].find(n=>n.dataset.view===view);return item?.closest('.nav-group')||null;}
function setOpenGroup(group){
  document.querySelectorAll('#nav .nav-group').forEach(g=>{const expanded=Boolean(group&&g===group);g.classList.toggle('open',expanded);g.querySelector('.nav-group-toggle')?.setAttribute('aria-expanded',String(expanded));});
}
function toggleNavGroup(id){const g=[...document.querySelectorAll('#nav .nav-group')].find(n=>n.dataset.group===id);if(!g)return;
  if(document.body.classList.contains('sidebar-collapsed')&&window.matchMedia('(min-width:761px)').matches){setSidebarCollapsed(false);setOpenGroup(g);return;}
  setOpenGroup(g.classList.contains('open')?null:g);
}
function setSidebarCollapsed(collapsed){document.body.classList.toggle('sidebar-collapsed',collapsed);safeStorage('local','set','awtutor_sidebar_collapsed_v2',collapsed?'true':'false');const btn=$('#sidebar-collapse');if(btn){btn.textContent=collapsed?'⇥':'⇤';btn.title=collapsed?'ขยายเมนู':'ยุบเมนู';btn.setAttribute('aria-label',collapsed?'ขยายเมนูด้านข้าง':'ยุบเมนูด้านข้าง');}}
function toggleSidebarCollapsed(){setSidebarCollapsed(!document.body.classList.contains('sidebar-collapsed'));}
function updateNavigation(view){
  const current=document.querySelector('#nav .nav-subitem[data-view="'+view+'"]');
  document.querySelectorAll('#nav [data-view]').forEach(n=>{const active=n.dataset.view===view;n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});
  document.querySelectorAll('#nav .nav-group').forEach(g=>g.classList.toggle('has-active',Boolean(g.querySelector('.nav-subitem.active'))));
  if(lastNavigationView!==view){const group=current?.closest('.nav-group')||null;setOpenGroup(group);lastNavigationView=view;}
}
function sectionTabs(view){
  const group=groupForView(view);if(!group)return '';
  const label=group.querySelector('.nav-group-toggle .nav-label')?.textContent||'';
  const items=[...group.querySelectorAll('.nav-subitem')];
  return `<nav class="workspace-tabs" aria-label="ส่วนงาน ${esc(label)}"><span class="workspace-tabs-title">${esc(label)}</span><div class="workspace-tabs-list">${items.map(n=>`<button type="button" data-view="${esc(n.dataset.view)}" class="workspace-tab${n.dataset.view===view?' active':''}" ${n.dataset.view===view?'aria-current="page"':''}>${esc(n.querySelector('.nav-label')?.textContent||'')}</button>`).join('')}</div></nav>`;
}
function toggleTheme(){const dark=document.body.classList.toggle('theme-dark');safeStorage('local','set','awtutor_ui_theme_v2',dark?'dark':'light');$('#theme-switch')?.setAttribute('aria-pressed',String(dark));}
function toggleMenu(show){$('#sidebar').classList.toggle('open',show);$('#mobile-backdrop').classList.toggle('open',show);}
function render(){const v=state.view;updateNavigation(v);$('#crumb').textContent=({dashboard:'ภาพรวม',students:'นักเรียนและคอร์ส',groups:'กลุ่มเรียน',schedule:'ตารางเรียน',manual:'ลงเวลาเรียน',import:'นำเข้า Google Meet',reviews:'ประวัติและแก้ไข',history:'ประวัติการเรียน',reports:'รายงาน',billing:'ค่าคาบรายชั่วโมง',leave:'ลาหยุดและชดเชย',journal:'สมุดบันทึกการสอน',notifications:'แจ้งเตือน',system:'สุขภาพและสำรองข้อมูล',reconcile:'ตรวจคาบที่ยังไม่ลงเวลา',finance:'การเงินและใบรับเงิน',timeline:'ไทม์ไลน์นักเรียน',portal:'Student Portal Manager'})[v]||'ภาพรวม';const dateEl=$('#top-date');if(dateEl)dateEl.textContent=new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(new Date());$('#mode-pill').textContent=state.mode==='live'?'GOOGLE SHEETS':state.mode==='needs_login'?'CONNECT GOOGLE':state.mode==='setup_required'?'SETUP GOOGLE':'DEMO DATA';$('#side-mode').textContent=state.mode==='live'?'LIVE DATABASE':state.mode==='needs_login'?'GOOGLE SIGN-IN REQUIRED':state.mode==='setup_required'?'GOOGLE SETUP REQUIRED':'DEMO MODE';$('#account-btn').textContent=state.mode==='live'?'G':'S';const views={dashboard,students,groups,schedule,manual,import:importPage,reviews,history:learningHistory,reports,billing:billingPage,leave:leavePanel,journal:teachingJournal,notifications:notificationsPanel,system:systemPage,reconcile:reconciliationPage,finance:financeProPage,timeline:studentTimelinePage,portal:portalManagerView};const gated=['needs_login','setup_required'].includes(state.mode);$('#app').innerHTML=gated?connectionGate():(sectionTabs(v)+(views[v]||dashboard)());document.querySelectorAll('.mobile-nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===v));}
function go(view){closeCalendarDrawer();state.view=view;toggleMenu(false);render();window.scrollTo(0,0);}
