function studentCard(s){
  const current=liveCourses(s.id),rem=currentStudentTotal(s.id),purchased=current.filter(c=>!isHourly(c)).reduce((n,c)=>n+num(c.purchased_minutes),0),ratio=purchased>0?Math.max(0,Math.min(100,Math.round(rem/purchased*100))):0;
  const initial=(s.name||'?').trim().slice(0,1).toUpperCase();
  const meetCount=activeAliasRows().filter(a=>a.student_id===s.id).length;
  const low=current.some(c=>!isHourly(c))&&rem<=120;
  return `<article class="student-card"><div class="student-card-head"><div class="student-avatar">${esc(initial)}</div><div class="student-title"><button class="student-name link-btn" data-action="student-detail" data-id="${esc(s.id)}">${esc(s.name)}</button><span class="student-fullname">${esc(s.full_name||'ยังไม่ระบุชื่อ–นามสกุล')}</span><small>${esc(s.id.slice(0,12))}</small></div>${pill(s.status==='deleted'?'ถังขยะ':s.status==='archived'?'พักเรียน':'กำลังเรียน',s.status==='active'?'green':s.status==='deleted'?'red':'')}</div>
  <div class="student-education"><div>⌂ <span>${esc(s.school||'ยังไม่ระบุโรงเรียน')}</span></div><small>ระดับชั้น ${esc(s.grade_level||'ยังไม่ระบุ')}${s.academic_year?' · ปี '+esc(s.academic_year):''}</small></div>
  <div class="student-balance">${current.some(c=>!isHourly(c))?`<div class="flex-between"><span>ชั่วโมงแพ็กเกจคงเหลือ</span><strong class="${low?'balance-low':'balance-good'}">${esc(nice(rem))}</strong></div><div class="progress" role="progressbar" aria-valuenow="${ratio}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill ${low?'low':''}" style="width:${ratio}%"></div></div>`:`<div class="flex-between"><span>เรียนรายชั่วโมง</span><strong class="balance-good">${esc(current.filter(isHourly).length)} คอร์ส</strong></div>`}<small>${current.length} คอร์สที่ใช้งาน${low?' · ชั่วโมงใกล้หมด':''}${unpaidInvoices().some(b=>b.student_id===s.id)?' · รอชำระ '+baht(unpaidInvoices().filter(b=>b.student_id===s.id).reduce((sum,b)=>sum+Number(b.amount_satang),0)):''}</small></div>
  <div class="student-course-chips">${current.slice(0,2).map(c=>`<span class="student-chip">${esc(c.title)}${isHourly(c)?' · รายชั่วโมง':''}</span>`).join('')||'<span class="student-chip quiet">ยังไม่มีคอร์ส</span>'}${current.length>2?`<span class="student-chip">+${current.length-2}</span>`:''}</div>
  <div class="student-card-foot"><span>⌁ Meet: ${meetCount} ชื่อ</span><span>♧ ${groupsOfStudent(s.id).length} กลุ่ม</span></div>${(()=>{const next=scheduleOccurrences(dateNow(),addCalendarDays(dateNow(),30)).find(x=>x.student_id===s.id||(x.group_id&&membersOf(x.group_id).includes(s.id)));return next?`<div class="student-next-date">▦ เรียนครั้งถัดไป: ${esc(displayReportDate(next.on_date))} ${esc(next.start_time)}–${esc(next.end_time)}</div>`:'<div class="student-next-date">ยังไม่กำหนดวันเรียนถัดไป</div>';})()}
  <div class="student-actions">${s.status==='deleted'?btnInline('♻ กู้คืน','restore-student',s.id):`${btnInline('เปิดโปรไฟล์ →','student-detail',s.id)}<details class="student-more"><summary aria-label="จัดการนักเรียน ${esc(s.name)}">···</summary><div class="student-more-popover">${btnInline('แก้ไขข้อมูล','edit-student',s.id)}${current.length?btnInline('ต่อคอร์ส','renew-student',s.id):''}${btnInline('เพิ่มคอร์ส','new-course-for',s.id)}</div></details>`}</div></article>`;
}
function students(){
  const deleted=all('Students').filter(s=>s.status==='deleted');
  const grades=[...new Set(all('Students').map(s=>s.grade_level).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'th'));
  const ss=all('Students').filter(s=>{
    if(state.showDeleted?s.status!=='deleted':s.status==='deleted')return false;
    if(state.studentGradeFilter!=='all'&&s.grade_level!==state.studentGradeFilter)return false;
    if(state.studentStatusFilter!=='all'&&s.status!==state.studentStatusFilter)return false;
    return norm([s.name,s.full_name,s.school,s.grade_level,s.email,s.aliases].join(' ')).includes(norm(state.search));
  }).sort((a,b)=>a.name.localeCompare(b.name,'th'));
  const actions=`<div class="button-row">${btn('＋ สร้างคอร์ส','add-course','soft')}${btn('＋ เพิ่มนักเรียน','add-student','primary')}</div>`;
  return `${head('PEOPLE / ENROLLMENT','Students & Courses','ข้อมูลนักเรียน โรงเรียน ระดับชั้น ชั่วโมงคงเหลือ และประวัติคอร์ส',actions)}
  <section class="panel"><div class="student-toolbar"><input class="search" id="student-search" placeholder="ค้นหาชื่อ โรงเรียน หรือระดับชั้น…" aria-label="ค้นหานักเรียน" value="${esc(state.search)}"><select id="student-grade-filter" aria-label="กรองระดับชั้น"><option value="all">ทุกระดับชั้น</option>${grades.map(g=>`<option value="${esc(g)}" ${state.studentGradeFilter===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="student-status-filter" aria-label="กรองสถานะ"><option value="all">ทุกสถานะ</option><option value="active" ${state.studentStatusFilter==='active'?'selected':''}>กำลังเรียน</option><option value="archived" ${state.studentStatusFilter==='archived'?'selected':''}>พักเรียน</option></select><div class="student-layout-toggle" aria-label="มุมมองรายชื่อนักเรียน"><button type="button" class="${state.studentLayout==='cards'?'selected':''}" data-action="student-view-cards" aria-pressed="${state.studentLayout==='cards'}">▦ การ์ด</button><button type="button" class="${state.studentLayout==='table'?'selected':''}" data-action="student-view-table" aria-pressed="${state.studentLayout==='table'}">☰ ตาราง</button></div><button class="btn small ${state.showDeleted?'soft':''}" data-action="toggle-deleted">${state.showDeleted?'← กลับรายการ':`♻ ถังขยะ (${deleted.length})`}</button></div>
  <p class="helper">แสดง ${ss.length} นักเรียน · แตะการ์ดเพื่อดูคอร์สและประวัติ หรือกดแก้ไขเพื่อเปลี่ยนโรงเรียน/ระดับชั้น</p>
  ${state.showDeleted?'<div class="note warn mt12">รายการในถังขยะถูกซ่อนจากการลงเวลาและ Google Meet แต่ข้อมูลเก่ายังคงอยู่</div>':''}
  ${state.studentLayout==='cards'?`<div class="student-cards">${ss.map(studentCard).join('')||'<div class="empty">ไม่พบนักเรียนตามเงื่อนไข</div>'}</div>`:`<div class="table-wrap mt20"><table><thead><tr><th>นักเรียน</th><th>โรงเรียน / ชั้น</th><th>คอร์ส</th><th>คงเหลือ</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${ss.map(s=>`<tr><td><button class="link-btn" data-action="student-detail" data-id="${esc(s.id)}">${esc(s.name)}</button><div class="td-secondary">${esc(s.full_name||'')}</div></td><td>${esc(s.school||'-')}<div class="td-secondary">${esc(s.grade_level||'-')}</div></td><td>${liveCourses(s.id).length}</td><td><strong class="amount">${esc(nice(currentStudentTotal(s.id)))}</strong></td><td>${pill(s.status,s.status==='active'?'green':'')}</td><td><div class="button-row">${btnInline('โปรไฟล์','student-detail',s.id)} ${s.status==='deleted'?btnInline('กู้คืน','restore-student',s.id):btnInline('แก้ไข','edit-student',s.id)}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ไม่พบนักเรียน</td></tr>'}</tbody></table></div>`}</section>${state.studentId?studentDetail(state.studentId)+studentEducationHistory(state.studentId):''}`;
}
function studentEducationHistory(id){const items=all('StudentEducationHistory').filter(h=>h.student_id===id).sort((a,b)=>String(b.changed_at).localeCompare(String(a.changed_at)));if(!items.length)return '';return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Academic History</h2><p class="panel-desc">ประวัติการเปลี่ยนโรงเรียนและระดับชั้น · ${items.length} ครั้ง</p></div></div><div class="timeline">${items.map(h=>`<div class="timeline-item"><strong>${esc(h.old_school||'ไม่ระบุ')} (${esc(h.old_grade_level||'-')}) → ${esc(h.new_school||'ไม่ระบุ')} (${esc(h.new_grade_level||'-')})</strong><small>${esc(h.changed_at)} · ปีการศึกษา ${esc(h.old_academic_year||'-')} → ${esc(h.new_academic_year||'-')}</small></div>`).join('')}</div></section>`;}
const btnInline=(label,action,id)=>`<button class="btn small" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
function studentDetail(id){
 const student=byId('Students',id);if(!student)return '';
 const cs=coursesOf(id),shown=state.showArchive?cs:cs.filter(c=>c.status==='active'||c.status==='held');
 const history=all('Attendance').filter(a=>a.student_id===id).sort((a,b)=>(byId('Sessions',b.session_id)?.date||'').localeCompare(byId('Sessions',a.session_id)?.date||''));
 return `<section class="panel" id="profile"><div class="panel-head"><div><h2 class="panel-title">${esc(student.name)} · Student Profile</h2><p class="panel-desc">${esc(student.full_name||'')} · ${esc(student.school||'ไม่ระบุโรงเรียน')} · ${esc(student.grade_level||'ไม่ระบุระดับชั้น')}</p><p class="helper">ประวัติการเรียนและวันที่เรียนทั้งหมดเชื่อมกับตารางเรียน</p></div><div class="button-row">${btnInline('แก้ไขข้อมูล','edit-student',id)} ${btnInline('＋ ลงคอร์สเพิ่ม','new-course-for',id)} ${btnInline('＋ ใช้คอร์สที่มีอยู่','assign-existing-course',id)} ${btnInline('＋ เพิ่มวันเรียน','schedule-for-student',id)} ${btnInline('ลาหยุด / พักเรียน','leave-for-student',id)} ${btnInline('ดูตารางเรียน','go-schedule','')} ${btnInline('ดูค่าคาบเรียน','go-billing','')} ${student.status!=='deleted'?`<button class="btn small danger" data-action="delete-student" data-id="${esc(id)}">ลบนักเรียน</button>`:btnInline('กู้คืน','restore-student',id)} <button class="btn small" data-action="hide-student">ปิด</button></div></div>
 <div class="metric-strip"><div><small>คอร์สที่ใช้ได้</small><b>${liveCourses(id).length}</b></div><div><small>ยอดค้างชำระรายชั่วโมง</small><b>${esc(baht(unpaidInvoices().filter(b=>b.student_id===id).reduce((n,b)=>n+billDueSatang(b),0)))}</b></div><div><small>ชั่วโมงแพ็กเกจคงเหลือ</small><b>${fmt(currentStudentTotal(id))}</b></div><div><small>วันที่สอนที่บันทึกแล้ว</small><b>${new Set(history.filter(a=>a.status==='approved').map(a=>byId('Sessions',a.session_id)?.date).filter(Boolean)).size} วัน</b></div></div>
 <div class="panel-head mt20"><h3 class="panel-title">Course Cycles</h3><button class="link-btn" data-action="toggle-archive">${state.showArchive?'ซ่อนคอร์สเก่า':'ประวัติคอร์สเก่า →'}</button></div>
 <div class="cards-grid">${shown.map(c=>`<div class="sheet-card"><div class="flex-between"><strong>${esc(c.title)}</strong>${pill(c.status,c.status==='active'?'green':'')}</div><p class="mini">รอบ ${esc(c.cycle_no)} · เริ่ม ${esc(displayReportDate(c.start_date))}</p><div class="big">${esc(isHourly(c)?baht(moneySatang(60,hourlyRate(c)))+' / ชม.':fmt(balance(c.id)))}</div><div class="mini">${isHourly(c)?'รายชั่วโมง · รอชำระ '+esc(baht(unpaidInvoices().filter(b=>b.course_id===c.id).reduce((n,b)=>n+billDueSatang(b),0))):'คงเหลือจากแพ็กเกจ '+esc(fmt(c.purchased_minutes))}</div><div class="button-row mt12">${c.status==='active'?`${btnInline('ต่อคอร์ส','renew-course',c.id)} ${!isHourly(c)?`${btnInline('เติมชั่วโมง','topup-course',c.id)} ${btnInline('ปรับยอด','adjust-course',c.id)}`:''}`:''}${btnInline('รายละเอียด','course-history',c.id)} ${btnInline('เงื่อนไข','course-policy',c.id)}</div></div>`).join('')||'<div class="empty">ยังไม่มีคอร์ส</div>'}</div>
 ${studentCalendar(id)}
 ${leaveStudentCard(id)}
 <div class="student-history-shortcut"><div><strong>ประวัติการเรียนที่บันทึกแล้ว</strong><p>ดูคาบเรียนที่เกิดขึ้นจริง พร้อมแก้ไขหรือยกเลิกรายการ ได้จากหน้า Learning History โดยไม่แสดงตารางซ้ำในโปรไฟล์</p></div><div class="button-row">${btnInline('ดูประวัตินักเรียนทั้งหมด','student-attendance-history',id)} ${btnInline('ดาวน์โหลดรายงานผู้ปกครอง','parent-report-student',id)} ${btnInline('ไทม์ไลน์นักเรียน','timeline-student',id)}</div></div>
 ${aliasPanel(id)}</section>`;
}
function monthOffset(month,step){const [y,m]=month.split('-').map(Number),d=new Date(Date.UTC(y,m-1+step,1));return d.toISOString().slice(0,7);}
function personalCalendarItems(studentId,from,to){
 const planned=scheduleOccurrences(from,to).filter(x=>(x.student_id===studentId||(x.group_id&&membersOf(x.group_id).includes(studentId)))&&!activeLeave(studentId,x.on_date)&&!scheduleException(x.id,x.on_date,studentId));
 const actual=all('Attendance').filter(a=>a.student_id===studentId&&a.status!=='cancelled').map(a=>({a,s:byId('Sessions',a.session_id)})).filter(x=>x.s&&x.s.status!=='cancelled'&&x.s.date>=from&&x.s.date<=to);
 // A recorded class replaces its scheduled occurrence even when its end time differed.
 // Match per student/date and overlapping tutor times; never suppress unrelated classes on the same day.
 const matchedPlan=p=>actual.some(({s})=>{
   if(s.date!==p.on_date||((p.group_id&&s.group_id)&&p.group_id!==s.group_id))return false;
   if(p.tutor&&s.tutor&&norm(p.tutor)!==norm(s.tutor))return false;
   const a=minutesOf(p.start_time),b=a+duration(p.start_time,p.end_time),c=minutesOf(s.start_time),d=c+duration(s.start_time,s.end_time);
   return Math.max(a,c)<Math.min(b,d)&&(p.start_time===s.start_time||Math.min(b,d)-Math.max(a,c)>=0.5*Math.min(b-a,d-c));
 });
 const items=planned.filter(p=>!matchedPlan(p)).map(p=>({id:p.id,date:p.on_date,start:p.start_time,end:p.end_time,label:p.group_id?(byId('Groups',p.group_id)?.name||'กลุ่มเรียน'):'เรียนเดี่ยว',kind:p.group_id?'group':'private',source:'planned',tutor:p.tutor}));
 for(const {a,s} of actual)items.push({id:s.id,date:s.date,start:s.start_time,end:s.end_time,label:courseTitle(a.course_id),kind:s.group_id?'group':'private',source:'recorded',tutor:s.tutor,minutes:a.deduct_minutes});
 for(const ex of all('ScheduleExceptions').filter(ex=>ex.student_id===studentId&&ex.kind==='rescheduled'&&ex.replacement_date>=from&&ex.replacement_date<=to)){const original=byId('Schedules',ex.schedule_id);if(original)items.push({id:ex.id,date:ex.replacement_date,start:ex.start_time,end:ex.end_time,label:'เลื่อนเฉพาะบุคคล · '+(original.group_id?byId('Groups',original.group_id)?.name:'เรียนเดี่ยว'),kind:original.group_id?'group':'private',source:'planned',tutor:original.tutor});}
 for(const m of all('MakeupCredits').filter(m=>m.student_id===studentId&&m.status==='scheduled'&&m.scheduled_date>=from&&m.scheduled_date<=to))items.push({id:m.id,date:m.scheduled_date,start:m.start_time,end:m.end_time,label:'ชดเชย · '+courseTitle(m.course_id),kind:'makeup',source:'makeup',tutor:m.tutor});
 for(const l of all('LeaveRecords').filter(l=>l.student_id===studentId&&l.status!=='cancelled')){for(let d=from;d<=to;d=addCalendarDays(d,1)){if(d>=l.start_date&&(!l.end_date||d<=l.end_date))items.push({id:l.id,date:d,start:'',end:'',label:l.kind==='pause'?'พักการเรียน':'ลาหยุด',kind:'leave',source:'leave',tutor:''});}}
 return items.sort((a,b)=>(a.date+a.start+a.id).localeCompare(b.date+b.start+b.id));
}
function studentCalendar(studentId){
 const month=dateValid(state.personalCalendarMonth+'-01')?state.personalCalendarMonth:dateNow().slice(0,7);
 const first=month+'-01',offset=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,gridStart=addCalendarDays(first,-offset),gridEnd=addCalendarDays(gridStart,41);
 const items=personalCalendarItems(studentId,gridStart,gridEnd),byDate=new Map();for(const i of items){if(!byDate.has(i.date))byDate.set(i.date,[]);byDate.get(i.date).push(i);}
 const day=state.personalCalendarDay&&state.personalCalendarDay.startsWith(month)?state.personalCalendarDay:first;
 const selected=byDate.get(day)||[],weeks=['จ','อ','พ','พฤ','ศ','ส','อา'];
 const cells=Array.from({length:42},(_,i)=>{const date=addCalendarDays(gridStart,i),entries=byDate.get(date)||[],isOther=date.slice(0,7)!==month;
 return `<button type="button" data-action="personal-calendar-day" data-id="${esc(date)}" class="personal-cal-cell ${isOther?'outside':''} ${day===date?'chosen':''} ${date===dateNow()?'today':''}" aria-label="${esc(displayReportDate(date))} ${entries.length} คาบ"><span class="personal-cal-date">${Number(date.slice(8))}</span><span class="personal-cal-dots">${entries.slice(0,3).map(x=>`<i class="${x.source==='recorded'?'recorded':x.kind}"></i>`).join('')}</span>${entries.slice(0,2).map(x=>`<span class="personal-cal-lesson ${x.source==='recorded'?'recorded':x.kind}">${esc(x.start)} ${esc(x.label)}</span>`).join('')}${entries.length>2?`<small>+${entries.length-2} คาบ</small>`:''}</button>`;}).join('');
 return `<section class="personal-calendar-wrap"><div class="panel-head mt20"><div><h3 class="panel-title">Student Schedule · ปฏิทินรายบุคคล</h3><p class="panel-desc">คลิกวันที่เพื่อดูตารางเรียนเดี่ยว กลุ่ม และคาบที่บันทึกแล้ว · ไม่ใช่ยอดหักชั่วโมงซ้ำ</p></div><div class="calendar-month-nav"><button type="button" data-action="personal-calendar-prev" aria-label="เดือนก่อนหน้า">‹</button><strong>${esc(thaiScheduleDate(first,{month:'long',year:'numeric'}))}</strong><button type="button" data-action="personal-calendar-next" aria-label="เดือนถัดไป">›</button><button type="button" class="btn small soft" data-action="personal-calendar-today">เดือนนี้</button></div></div><div class="personal-calendar-scroll"><div class="personal-calendar-weekdays">${weeks.map(x=>`<span>${x}</span>`).join('')}</div><div class="personal-calendar-grid">${cells}</div></div><div class="personal-calendar-legend"><span><i class="private"></i> เรียนเดี่ยว</span><span><i class="group"></i> เรียนกลุ่ม</span><span><i class="recorded"></i> บันทึกแล้ว</span><span><i class="makeup"></i> ชดเชย</span><span><i class="leave"></i> ลา/พัก</span></div><div class="personal-day-detail"><strong>${esc(displayReportDate(day))} · ${selected.length} คาบ</strong>${selected.map(x=>`<div class="personal-day-item"><div><b>${esc(x.start)}–${esc(x.end)}</b> · ${esc(x.label)}<small>${esc(x.tutor||'ไม่ระบุติวเตอร์')} · ${x.source==='recorded'?'เรียนและบันทึกแล้ว · '+nice(x.minutes):x.source==='leave'?'ระงับคาบตามช่วงวันที่แจ้งลา/พัก':x.source==='makeup'?'คาบชดเชยที่นัดไว้ · รอลงเวลาจริง':'ตามตาราง (ยังไม่ใช่ชั่วโมงที่เรียนจริง)'}</small></div>${btnInline('ดูรายละเอียด','calendar-drawer',(x.source==='recorded'?'recorded':x.source==='makeup'?'makeup':x.source==='leave'?'leave':'planned')+'|'+x.id+'|'+x.date+'|'+studentId)}</div>`).join('')||'<p class="helper">วันนี้ไม่มีคาบที่กำหนดหรือบันทึกไว้</p>'}</div></section>`;
}
function aliasPanel(studentId){const rows=all('MeetAliases').filter(x=>x.student_id===studentId&&x.status==='active');return `<div class="panel-head mt20"><h3 class="panel-title">Google Meet Identities</h3>${btnInline('＋ เพิ่มชื่อ Meet','add-meet-alias',studentId)}</div><div class="alias-list">${rows.map(a=>`<div class="alias-card"><span><strong>${esc(a.meet_name||'(ไม่มีชื่อ)')}</strong><small>${esc(a.email||'')} · ยืนยัน ${esc(a.verified_at?.slice(0,10)||'')}</small></span>${btnInline('ยกเลิกการจดจำ','remove-meet-alias',a.id)}</div>`).join('')||'<p class="helper">ยังไม่มีชื่อ Meet ที่ยืนยัน (ชื่อในข้อมูลนักเรียนเดิมยังสามารถใช้จับคู่ได้)</p>'}</div>`;}
function openAliasForm(studentId){const s=byId('Students',studentId);if(!s||s.status!=='active')return;modal('จดจำชื่อ Google Meet · '+s.name,`<form id="alias-form" class="form"><input type="hidden" name="alias-student" value="${esc(studentId)}">${field('alias-name','ชื่อที่ปรากฏใน Google Meet','text','','required')}${field('alias-email','อีเมล Meet (ถ้ามี)','email','','')}<div class="note">หากชื่อหรืออีเมลนี้เชื่อมกับนักเรียนคนอื่น ระบบจะไม่อนุญาตให้บันทึกจนกว่าจะแก้ไขความขัดแย้ง</div><button class="btn primary" type="submit">ยืนยันและจดจำชื่อนี้</button></form>`);}
async function saveAlias(f){const id=inputVal(f,'alias-student'),name=inputVal(f,'alias-name'),email=inputVal(f,'alias-email');if(!byId('Students',id)||!name)throw Error('กรุณาเลือกนักเรียนและชื่อ Meet');const conflict=aliasConflict(name,email,id);if(conflict)throw Error('ชื่อหรืออีเมลนี้สัมพันธ์กับ '+conflict+' กรุณาตรวจสอบก่อน');if(aliasExists(name,email,id))throw Error('ชื่อ Meet นี้เคยบันทึกไว้แล้ว');await commit({add:{MeetAliases:[aliasRow(id,name,email)],Audit:[saveAudit('meet_alias_verified',id,{name,email})]}});closeModal();toast('บันทึกชื่อ Meet สำหรับการจับคู่ครั้งต่อไปแล้ว');}
async function removeAlias(id){const a=byId('MeetAliases',id);if(!a||a.status!=='active')return;if(!confirm('ยกเลิกการจดจำชื่อ Meet นี้? รายงานเก่าจะยังอยู่'))return;await commit({update:{MeetAliases:[{...a,status:'inactive'}]},add:{Audit:[saveAudit('meet_alias_unlinked',a.student_id,{name:a.meet_name})]}});toast('ยกเลิกการจดจำชื่อ Meet แล้ว');}
function groups(){return `${head('GROUP LEARNING / MEMBERS','Class Groups','นักเรียนหนึ่งคนมีได้ทั้งคอร์สเดี่ยวและหลายกลุ่ม พร้อมเก็บประวัติสมาชิก',btn('＋ สร้างกลุ่มเรียน','add-group','primary'))}
  <div class="note">การเพิ่มหรือย้ายสมาชิกไม่เปลี่ยนประวัติคาบเรียนเก่า · กำหนดเวลาอ้างอิงเริ่มต้นเฉพาะกลุ่มได้</div>
  <div class="cards-grid mt20">${all('Groups').map(g=>{const ids=membersOf(g.id),r=ruleFor('group',g.id);return `<div class="sheet-card"><div class="flex-between"><strong>${esc(g.name)}</strong>${pill(ids.length+' students','green')}</div><div class="mini" style="line-height:1.8">${ids.map(studentName).map(esc).join(' · ')||'ยังไม่มีสมาชิก'}</div><div class="mini mt12">กติกาตัดชั่วโมง: ${esc(r?.basis||'tutor')} · บันทึกสมาชิก ${all('GroupMemberships').filter(x=>x.group_id===g.id).length} เหตุการณ์</div><div class="button-row mt20">${btnInline('แก้ไขสมาชิก','edit-group',g.id)} ${btnInline('ประวัติสมาชิก','group-members',g.id)} ${btnInline('กติกาเริ่มต้น','group-rule',g.id)} ${btnInline('ลงเวลาเรียน','record-group',g.id)}</div></div>`}).join('')||'<div class="empty">ยังไม่มีกลุ่มเรียน เพิ่มกลุ่มเพื่อเริ่มต้น</div>'}</div>`;}

