function importReview(d){
  const status=reportStatus(d,state.importIndex),suggest=recommendedGroup(d);
  return `<section class="panel import-people-panel" id="import-people"><div class="panel-head"><div class="import-section-title"><span class="import-step">04</span><div><h2 class="panel-title">Student & Meet Matching</h2><p class="panel-desc">ตรวจรายชื่อใน ${esc(d.filename)} · ผู้ที่จับคู่แล้วจะเสนอคอร์สให้อัตโนมัติ</p></div></div>${pill(status.label,status.tone)}</div>
  ${addMeetWarnings(d)}${importIntelligentWarnings(d)}
  ${suggest?`<div class="note">อาจตรงกับกลุ่ม <strong>${esc(suggest.name)}</strong> ${btn('ใช้กลุ่มนี้','suggest-import-group','small soft').replace('data-action=',`data-id="${esc(suggest.id)}" data-action=`)}</div>`:''}
  <div class="note">วันที่เรียนแสดงในตารางสรุปด้านบนตามแต่ละไฟล์โดยอัตโนมัติ · สีเขียว = จับคู่แล้ว · สีเหลือง = ต้องตรวจสอบ · สีแดง = ยังจับคู่ไม่ได้ · ติวเตอร์ไม่ถูกนำไปตัดชั่วโมง</div>
  <div id="import-participants">${importParticipants(d)}</div>
  <div class="import-final-actions"><div><strong>05 · Final Review</strong><p class="helper">เปิดหน้าสรุปวันที่ นักเรียน คอร์ส และยอดชั่วโมงก่อนยืนยันทุกครั้ง</p></div><div class="button-row"><button type="button" class="btn primary" data-action="preview-batch-import">สรุปก่อนบันทึกไฟล์ที่เลือก →</button><button type="button" class="btn soft" data-action="preview-import">สรุปเฉพาะไฟล์นี้</button></div></div></section>`;
}
function importParticipants(d){
  return `<div class="table-wrap import-participant-table"><table><thead><tr><th>เลือก</th><th>ชื่อจาก Google Meet</th><th>นักเรียน</th><th>คอร์สที่จะตัด</th><th>เข้าร่วมจริง</th><th>หักนาที</th><th>สถานะ / ตัวเลือก</th></tr></thead><tbody>${d.people.map((p,i)=>{
    const tutor=i===d.tutorIndex,student=p.studentId?byId('Students',p.studentId):null;
    const effectiveGroup=d.split?(p.classChoice||'private'):d.classType==='group'?d.groupId:'private';
    const groupChoice=effectiveGroup==='private'?'':effectiveGroup;
    const course=student?proposedCourse(student.id,groupChoice?'group':'private',groupChoice):null;
    const val=p.manualMinutes===null?adjustedByRule(calculatedImport(d,p),ruleFor('group',groupChoice)):Number(p.manualMinutes);
    const check=tutor?{level:'tutor',text:'ติวเตอร์',note:''}:getPersonStatus(d,p);
    const myGroups=student?groupsOfStudent(student.id):[];
    return `<tr class="status-${check.level}"><td><input type="checkbox" data-import-include="${i}" aria-label="เลือก ${esc(p.name)}" ${p.include&&!tutor?'checked':''} ${tutor?'disabled':''}></td>
      <td><strong>${esc(p.name)}</strong><small>${esc(p.email||'ไม่มีอีเมล')}</small><small>เข้า ${esc(p.join||'–')} · ออก ${esc(p.leave||'–')}</small></td>
      <td>${tutor?pill('ติวเตอร์','blue'):`<select data-import-student="${i}" aria-label="จับคู่นักเรียน ${esc(p.name)}">${studentOptions(p.studentId)}</select>`}</td>
      <td>${tutor?'—':`<select data-import-course="${i}" aria-label="คอร์สของ ${esc(p.name)}">${courseOptions(p.studentId,p.courseId||course?.id)}</select>`}</td>
      <td class="nowrap">${esc(nice(p.actual))}</td><td>${tutor?'—':`<input type="number" data-import-minutes="${i}" aria-label="นาทีหักของ ${esc(p.name)}" min="0" max="720" value="${num(p.manualMinutes??val)}">`}</td>
      <td>${pill(check.text,check.level==='unknown'||check.level==='conflict'?'red':check.level==='different'?'gold':check.level==='match'?'green':'blue')}
      ${!tutor?`<details class="person-options"><summary>รายละเอียดเพิ่มเติม</summary><label class="check"><input type="checkbox" data-import-remember="${i}" ${p.remember?'checked':''} ${!p.studentId?'disabled':''}> จดจำชื่อ Meet</label>${d.split?`<div class="field"><label>คลาสของนักเรียนนี้</label><select data-import-class="${i}"><option value="private" ${effectiveGroup==='private'?'selected':''}>เรียนเดี่ยว</option>${myGroups.map(g=>`<option value="${esc(g.id)}" ${effectiveGroup===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div>`:''}<small>${esc(check.note||p.matchReason||'')}</small></details>`:''}</td></tr>`;
  }).join('')}</tbody></table></div>`;
}

function calculatedImport(d,p){const tutor=d.people[d.tutorIndex],basis=p.timeBasis||d.basis;if(basis==='custom')return num(p.manualMinutes??p.actual);if(basis==='student')return p.actual;if(basis==='overlap')return tutor?overlapMinutes(tutor.segments,p.segments):p.actual;if(basis==='person')return d.people[d.sourceIndex]?.actual??p.actual;return d.timeOverrideStart&&d.timeOverrideEnd?duration(d.timeOverrideStart,d.timeOverrideEnd):(tutor?.actual??p.actual);}
function overlapMinutes(a,b){const intersections=[];for(const aa of a)for(const bb of b){const x=Math.max(aa[0],bb[0]),y=Math.min(aa[1],bb[1]);if(y>x)intersections.push([x,y]);}return mergeSegments(intersections).reduce((sum,s)=>sum+s[1]-s[0],0);}
function billingPage(){
 const bills=all('Billing').sort((a,b)=>b.created_at.localeCompare(a.created_at));
 const unpaid=bills.filter(b=>['unpaid','partial'].includes(b.status)),total=unpaid.reduce((n,b)=>n+billDueSatang(b),0);
 return `${partialPaymentPanel()}${billingPaymentHistory()}${head('PAY PER HOUR / BILLING','ค่าคาบเรียนรายชั่วโมง','บันทึกคาบก่อน → รอชำระ → กดยืนยันรับชำระแล้วจึงปิดยอด',btn('ดูประวัติการเรียน','go-history','soft'))}
 <div class="metric-strip"><div><small>ค่าคาบค้างชำระ</small><b>${esc(baht(total))}</b></div><div><small>รายการรอชำระ</small><b>${unpaid.length}</b></div><div><small>ชำระแล้ว</small><b>${bills.filter(b=>b.status==='paid').length} รายการ</b></div></div>
 <section class="panel mt20"><div class="panel-head"><h2 class="panel-title">รายการรายชั่วโมง</h2></div><div class="table-wrap"><table><thead><tr><th>วันที่เรียน</th><th>นักเรียน</th><th>คอร์ส / รอบ</th><th>ระยะเวลา</th><th>ราคา/ชม.</th><th>ยอดเงิน</th><th>สถานะ</th><th>ดำเนินการ</th></tr></thead><tbody>${bills.map(b=>{const ses=byId('Sessions',b.session_id),c=byId('Courses',b.course_id);return `<tr><td>${esc(ses?.date||'-')}</td><td>${esc(studentName(b.student_id))}</td><td>${esc(c?.title||'-')} · รอบ ${esc(c?.cycle_no||'-')}</td><td>${esc(nice(b.minutes))}</td><td>${esc(baht(moneySatang(60,b.rate_baht)))}</td><td><strong>${esc(baht(b.amount_satang))}</strong></td><td>${pill(b.status==='unpaid'?'รอชำระ':b.status==='partial'?'ชำระบางส่วน':b.status==='paid'?'ชำระแล้ว':b.status==='refund_due'?'รอยืนยันคืนเงิน':'ยกเลิก',b.status==='paid'?'green':b.status==='unpaid'?'gold':'')}</td><td>${['unpaid','partial'].includes(b.status)?btnInline('รับชำระแล้ว','mark-paid',b.id):b.status==='refund_due'?btnInline('ยืนยันคืนเงินแล้ว','mark-refunded',b.id):'-'}</td></tr>`;}).join('')||'<tr><td colspan="8">ยังไม่มีค่าคาบรายชั่วโมง</td></tr>'}</tbody></table></div></section>`;
}
function openPayment(billId){const b=byId('Billing',billId);if(!b||b.status!=='unpaid')throw Error('ไม่พบรายการรอชำระ');const ses=byId('Sessions',b.session_id);modal('ยืนยันรับชำระค่าคาบ',`<form id="payment-form" class="form"><input type="hidden" name="bill-id" value="${esc(b.id)}"><div class="note"><strong>${esc(studentName(b.student_id))}</strong> · ${esc(ses?.date||'-')} · ${esc(nice(b.minutes))}<br>ยอดเงิน <strong>${esc(baht(b.amount_satang))}</strong></div>${selectField('pay-method','วิธีรับชำระ',`<option value="transfer">โอนเงิน</option><option value="cash">เงินสด</option><option value="other">อื่น ๆ</option>`)}${field('pay-note','หมายเหตุการชำระ','text','','')}<label class="summary-agree"><input type="checkbox" name="confirm-paid" required><span>ยืนยันว่าได้รับเงินจริงแล้ว</span></label><button class="btn primary" type="submit">ยืนยันรับชำระและปิดยอด</button></form>`);}
async function markPaid(form){const b=byId('Billing',inputVal(form,'bill-id'));if(!b||b.status!=='unpaid')throw Error('รายการนี้ไม่รอชำระแล้ว');if(!form.querySelector('[name="confirm-paid"]')?.checked)throw Error('กรุณายืนยันว่ารับเงินจริงแล้ว');await commit({update:{Billing:[{...b,status:'paid',paid_at:now(),payment_method:inputVal(form,'pay-method'),note:inputVal(form,'pay-note'),updated_at:now()}]},add:{Audit:[saveAudit('hourly_payment_received',b.id,{amount_satang:b.amount_satang,method:inputVal(form,'pay-method')})]}});closeModal();toast('บันทึกการรับชำระแล้ว');}
async function markRefunded(id){const b=byId('Billing',id);if(!b||b.status!=='refund_due')throw Error('รายการนี้ไม่ต้องคืนเงิน');if(!confirm('ยืนยันว่าได้คืนเงินจริงให้ผู้เรียนแล้ว?'))return;await commit({update:{Billing:[{...b,status:'refunded',updated_at:now()}]},add:{Audit:[saveAudit('hourly_refund_confirmed',b.id,{amount_satang:billPaidSatang(b)})]}});toast('บันทึกคืนเงินจริงแล้ว');}
function reviews(){const sessions=sessionsSorted().filter(s=>state.filter==='all'||s.status===state.filter);return `${head('APPROVAL / LEDGER','ประวัติและแก้ไข','คาบที่บันทึกแล้ว การยกเลิก และการจัดการรายการค้างเดิม')}<div class="toolbar"><select class="pill-select" id="history-filter"><option value="all" ${state.filter==='all'?'selected':''}>ทั้งหมด</option><option value="pending" ${state.filter==='pending'?'selected':''}>รายการเก่าที่ยังไม่ตัด</option><option value="approved" ${state.filter==='approved'?'selected':''}>บันทึกและตัดแล้ว</option><option value="cancelled" ${state.filter==='cancelled'?'selected':''}>Cancelled</option></select><div class="button-row"><button type="button" class="btn small soft" data-action="review-select-all">☑ เลือก Pending ทั้งหมด</button><button type="button" class="btn small" data-action="review-select-none">ล้างที่เลือก</button><button type="button" class="btn small primary" data-action="review-approve-selected">สรุปก่อนอนุมัติ (<span id="review-selected-count">${state.reviewSelection.length}</span>)</button></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>SELECT</th><th>DATE / TIME</th><th>METHOD</th><th>STUDENTS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${s.status==='pending'?`<input type="checkbox" aria-label="เลือกคาบ ${esc(s.date)}" data-review-check="${esc(s.id)}" ${state.reviewSelection.includes(s.id)?'checked':''}>`:'—'}</td><td>${esc(s.date)}<div class="td-secondary">${esc(s.start_time)}–${esc(s.end_time)}</div></td><td>${esc(s.mode)}<div class="td-secondary truncate">${esc(s.source_file||s.tutor)}</div></td><td>${all('Attendance').filter(a=>a.session_id===s.id).length}</td><td>${pill(sessionStatusText(s.status),s.status==='approved'?'green':s.status==='pending'?'gold':'red')}</td><td><div class="button-row">${btnInline('รายละเอียด','session-detail',s.id)} ${s.status==='pending'?btnInline('ตัดชั่วโมงรายการเก่า','approve-session',s.id):''}</div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีประวัติคาบเรียน</td></tr>'}</tbody></table></div></div>`;}
function learningHistory(){
  const sessions=all('Sessions').filter(s=>dateValid(s.date)).sort((a,b)=>b.date.localeCompare(a.date)||b.start_time.localeCompare(a.start_time));
  const tutors=[...new Set(sessions.map(s=>s.tutor).filter(Boolean))].sort();
  const selected=sessions.filter(s=>(!state.historyFrom||s.date>=state.historyFrom)&&(!state.historyTo||s.date<=state.historyTo)&&(state.historyStatus==='all'||s.status===state.historyStatus)&&(!state.historyTutor||s.tutor===state.historyTutor)&&(!state.historyGroup||s.group_id===state.historyGroup)&&(!state.historyStudent||all('Attendance').some(a=>a.session_id===s.id&&a.student_id===state.historyStudent))&&(!state.historyCourse||all('Attendance').some(a=>a.session_id===s.id&&a.course_id===state.historyCourse)));
  // Show only the booked/deducted minutes, not a second total computed from session clock ranges.
  // Cancelled attendance must not inflate the total; student/course filters apply to the hours too.
  const historyAttends=s=>activeAttendanceRows(s.id).filter(a=>(!state.historyStudent||a.student_id===state.historyStudent)&&(!state.historyCourse||a.course_id===state.historyCourse));
  const deductedInSession=s=>s.status==='approved'?historyAttends(s).filter(a=>a.status==='approved').reduce((n,a)=>n+num(a.deduct_minutes),0):0;
  const totalDeduct=selected.reduce((n,s)=>n+deductedInSession(s),0);
  const oneRow=s=>{const attends=historyAttends(s),label=s.group_id?byId('Groups',s.group_id)?.name||'กลุ่มเรียน':attends.map(a=>studentName(a.student_id)).join(', ')||'ไม่มีผู้เรียน';return `<tr><td><strong>${esc(displayReportDate(s.date))}</strong></td><td class="nowrap">${esc(s.start_time)}–${esc(s.end_time)}</td><td>${esc(s.tutor||'-')}</td><td><strong>${esc(label)}</strong><small>${attends.length} นักเรียน · ${esc(s.mode)}</small></td><td><strong>${s.status==='approved'?esc(nice(deductedInSession(s))):'ยังไม่ตัด'}</strong></td><td>${pill(s.status,s.status==='approved'?'green':s.status==='pending'?'gold':'red')}</td><td>${btnInline('รายละเอียด','session-detail',s.id)}</td></tr>`};
  const groups=new Map();for(const s of selected){if(!groups.has(s.date))groups.set(s.date,[]);groups.get(s.date).push(s);}
  return `${head('ATTENDANCE / HISTORY','Learning History','ค้นหาตามวันเรียน ติวเตอร์ นักเรียน กลุ่ม และสถานะ · เปิดรายละเอียดคาบได้')}
  <section class="panel"><div class="grid-3 history-filter-grid"><div class="field"><label for="history-from">ตั้งแต่วันที่</label><input type="date" id="history-from" value="${esc(state.historyFrom)}"></div><div class="field"><label for="history-to">ถึงวันที่</label><input type="date" id="history-to" value="${esc(state.historyTo)}"></div><div class="field"><label for="history-tutor">ติวเตอร์</label><select id="history-tutor"><option value="">ทุกคน</option>${tutors.map(v=>`<option value="${esc(v)}" ${state.historyTutor===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>
  <div class="field"><label for="history-student">นักเรียน</label><select id="history-student">${studentOptions(state.historyStudent).replace('— เลือกนักเรียน —','ทุกคน')}</select></div><div class="field"><label for="history-group">กลุ่มเรียน</label><select id="history-group"><option value="">ทุกกลุ่ม</option>${all('Groups').map(g=>`<option value="${esc(g.id)}" ${state.historyGroup===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><div class="field"><label for="history-course">คอร์ส / รอบเรียน</label><select id="history-course"><option value="">ทุกคอร์ส</option>${all('Courses').map(c=>`<option value="${esc(c.id)}" ${state.historyCourse===c.id?'selected':''}>${esc(studentName(c.student_id))} · ${esc(c.title)} รอบ ${esc(c.cycle_no)}</option>`).join('')}</select></div><div class="field"><label for="history-status">สถานะ</label><select id="history-status">${['all','pending','approved','cancelled'].map(x=>`<option value="${x}" ${state.historyStatus===x?'selected':''}>${x==='all'?'ทั้งหมด':sessionStatusText(x)}</option>`).join('')}</select></div></div>
  <div class="history-switch"><div class="button-row"><button class="btn small ${state.historyLayout==='table'?'primary':'soft'}" data-action="history-view-table">☷ ตาราง</button><button class="btn small ${state.historyLayout==='day'?'primary':'soft'}" data-action="history-view-day">▦ แยกตามวัน</button></div>${btn('ล้างตัวกรอง','history-clear','small')}</div>
  <div class="import-metrics history-metrics"><div><small>จำนวนวันที่เรียน</small><strong>${groups.size}</strong></div><div><small>จำนวนคาบ</small><strong>${selected.length}</strong></div><div><small>ชั่วโมงที่ตัด</small><strong>${esc(nice(totalDeduct))}</strong></div></div>
  ${state.historyLayout==='day'?`<div class="history-days">${[...groups].map(([date,ss])=>`<details class="history-day" open><summary><strong>${esc(displayReportDate(date))}</strong><span>${ss.length} คาบ · ตัด ${esc(nice(ss.reduce((n,s)=>n+deductedInSession(s),0)))}</span></summary><div class="table-wrap"><table><thead><tr><th>วัน</th><th>เวลา</th><th>ติวเตอร์</th><th>นักเรียน/กลุ่ม</th><th>ชั่วโมงที่ตัด</th><th>สถานะ</th><th>ดู</th></tr></thead><tbody>${ss.map(oneRow).join('')}</tbody></table></div></details>`).join('')||'<div class="empty">ไม่มีประวัติที่ตรงกับตัวกรอง</div>'}</div>`:`<div class="table-wrap history-results"><table><thead><tr><th>วันที่</th><th>เวลา</th><th>ติวเตอร์</th><th>นักเรียน/กลุ่ม</th><th>ชั่วโมงที่ตัด</th><th>สถานะ</th><th>ดู</th></tr></thead><tbody>${selected.map(oneRow).join('')||'<tr><td colspan="7" class="empty">ไม่พบคาบเรียนที่ตรงกับตัวกรอง</td></tr>'}</tbody></table></div>`}
  <p class="helper mt12">แสดงเฉพาะชั่วโมงที่บันทึกและอนุมัติแล้ว ไม่นับรายการ Pending หรือผู้เรียนที่ถูกยกเลิก · คอร์สรายชั่วโมงใช้เวลาที่บันทึกคำนวณค่าคาบ</p></section>`;
}
function parentReportRows(){
 const studentId=state.reportStudent,month=state.reportMonth,courseId=state.reportCourse;
 if(!studentId||!byId('Students',studentId)||!/^\d{4}-\d{2}$/.test(month))return [];
 return all('Attendance').filter(a=>a.student_id===studentId&&a.status==='approved'&&(!courseId||a.course_id===courseId)).map(a=>({a,s:byId('Sessions',a.session_id)})).filter(({s})=>s&&s.status==='approved'&&s.date?.slice(0,7)===month).sort((x,y)=>(x.s.date+x.s.start_time).localeCompare(y.s.date+y.s.start_time));
}
function parentReportTable(rows){return `<div class="table-wrap parent-report-table"><table><thead><tr><th>วันที่เรียน</th><th>เวลา</th><th>คอร์ส / รอบ</th><th>ผู้สอน</th><th>เข้าร่วมจริง</th><th>บันทึกชั่วโมง</th><th>ค่าคาบ / สถานะ</th></tr></thead><tbody>${rows.map(({a,s})=>{const bill=billingOf(a.id);return `<tr><td>${esc(displayReportDate(s.date))}</td><td class="nowrap">${esc(s.start_time)}–${esc(s.end_time)}</td><td>${esc(courseTitle(a.course_id))}</td><td>${esc(s.tutor||'-')}</td><td>${esc(nice(a.actual_minutes))}</td><td>${esc(nice(a.deduct_minutes))}</td><td>${bill?esc(baht(bill.amount_satang))+' · '+esc(bill.status==='paid'?'ชำระแล้ว':'ยังไม่ปิดยอด'):'แพ็กเกจ'}</td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">ไม่พบคาบที่บันทึกสำเร็จในเดือนและคอร์สที่เลือก</td></tr>'}</tbody></table></div>`;}
function parentReportPanel(){
 const studentId=state.reportStudent,month=state.reportMonth,courseId=state.reportCourse;
 const rows=parentReportRows(),actual=rows.reduce((n,x)=>n+num(x.a.actual_minutes),0),recorded=rows.reduce((n,x)=>n+num(x.a.deduct_minutes),0),dates=new Set(rows.map(x=>x.s.date));
 const courses=studentId?coursesOf(studentId):[];
 return `<section class="panel parent-report"><div class="panel-head"><div><span class="section-overline">PARENT / GUARDIAN</span><h2 class="panel-title">รายงานเวลาเรียนรายบุคคล</h2><p class="panel-desc">กรองนักเรียน เดือน และคอร์ส รวมถึงคอร์สที่ต่อรอบหรือปิดแล้ว ก่อนส่งให้ผู้ปกครอง</p></div></div><div class="grid-3 parent-report-filters"><div class="field"><label for="parent-report-student">นักเรียน</label><select id="parent-report-student">${studentOptions(studentId)}</select></div><div class="field"><label for="parent-report-month">เดือนที่เรียน</label><input type="month" id="parent-report-month" value="${esc(month)}"></div><div class="field"><label for="parent-report-course">คอร์ส / รอบเรียน</label><select id="parent-report-course"><option value="">ทุกคอร์สของนักเรียน</option>${courses.map(c=>`<option value="${esc(c.id)}" ${courseId===c.id?'selected':''}>${esc(c.title)} · รอบ ${esc(c.cycle_no)}${c.status!=='active'?' (เก่า)':''}</option>`).join('')}</select></div></div>${!studentId?'<div class="note">เลือกนักเรียนก่อน เพื่อป้องกันการรวมข้อมูลของหลายคนในรายงานผู้ปกครอง</div>':`<div class="parent-report-metrics"><div><small>วันที่เรียน</small><b>${dates.size} วัน</b></div><div><small>จำนวนคาบ</small><b>${rows.length}</b></div><div><small>เวลาเข้าร่วมจริง</small><b>${esc(nice(actual))}</b></div><div><small>ชั่วโมงที่บันทึก</small><b>${esc(nice(recorded))}</b></div></div>${parentReportTable(rows)}<p class="helper">แสดงเฉพาะคาบที่บันทึกสำเร็จ ไม่รวมรายการยกเลิกหรือ Pending · ชั่วโมงที่บันทึกอาจต่างจากเวลาเข้าร่วมจริงตามเงื่อนไขของคอร์ส</p><div class="button-row parent-report-actions"><button type="button" class="btn soft" data-action="parent-report-csv" ${rows.length?'':'disabled'}>⇩ ดาวน์โหลด Excel/CSV</button><button type="button" class="btn primary" data-action="parent-pdf-direct" ${rows.length?'':'disabled'}>⇩ ดาวน์โหลด PDF</button><button type="button" class="btn soft" data-action="parent-report-pdf" ${rows.length?'':'disabled'}>พิมพ์ PDF</button></div>`}</section>`;
}
function parentCsv(){
 const rows=parentReportRows();if(!rows.length)throw Error('ไม่มีรายงานของเดือนและคอร์สที่เลือก');
 const header=['วันที่เรียน','เริ่ม','สิ้นสุด','นักเรียน','คอร์ส/รอบ','ติวเตอร์','เข้าร่วมจริง','ชั่วโมงที่บันทึก','ค่าคาบ (บาท)','สถานะชำระ'];
 const csvRows=[header,...rows.map(({a,s})=>{const b=billingOf(a.id);return [s.date,s.start_time,s.end_time,studentName(a.student_id),courseTitle(a.course_id),s.tutor||'',nice(a.actual_minutes),nice(a.deduct_minutes),b?(b.amount_satang/100).toFixed(2):'',b?(b.status==='paid'?'ชำระแล้ว':b.status==='unpaid'?'ค้างชำระ':b.status):'แพ็กเกจ'];})];
 const text='\ufeff'+csvRows.map(r=>r.map(v=>{let cell=String(v??'');if(/^[=+@\-\t\r]/.test(cell))cell="'"+cell;return '"'+cell.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');
 const b=new Blob([text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`AreWarin-Student-${state.reportMonth}-${state.reportStudent.slice(0,8)}.csv`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function parentPdf(){
 const rows=parentReportRows();if(!rows.length)throw Error('ไม่มีรายการให้พิมพ์');const student=byId('Students',state.reportStudent),total=rows.reduce((n,r)=>n+num(r.a.deduct_minutes),0),actual=rows.reduce((n,r)=>n+num(r.a.actual_minutes),0);const title='รายงานเวลาเรียน '+student.name+' · '+state.reportMonth;
 const report=`<!doctype html><html lang="th"><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:15mm}body{font:12px Arial,'Noto Sans Thai',sans-serif;color:#243e31}h1{font-size:23px;margin:4px 0 8px;color:#174b3a}h2{font-size:14px}p{margin:6px 0}.brand{font-size:10px;letter-spacing:2px;font-weight:bold;color:#22684a}.sub{color:#64756b}table{border-collapse:collapse;width:100%;font-size:10px;margin-top:18px}th,td{border-bottom:1px solid #dce5df;padding:9px 7px;text-align:left;vertical-align:top}th{background:#edf5ee;color:#284a38}tr{break-inside:avoid}.summary{display:flex;gap:32px;border-top:1px solid #e0e9e2;padding:12px 0;margin:13px 0}.summary strong{display:block;font-size:15px;margin-top:3px}footer{margin-top:22px;padding-top:10px;border-top:1px solid #dce5df;color:#758479;font-size:9px}button{padding:9px 14px;border:0;background:#174b3a;color:white;cursor:pointer}@media print{button{display:none}}</style></head><body><div class="brand">AREWARIN TUTOR</div><h1>รายงานเวลาเรียนรายบุคคล</h1><p>นักเรียน: <b>${esc(student.name)}</b> ${student.full_name?'· '+esc(student.full_name):''}</p><p>เดือน: <b>${esc(state.reportMonth)}</b> · คอร์ส: <b>${esc(state.reportCourse?courseTitle(state.reportCourse):'ทุกคอร์ส')}</b></p><div class="summary"><span>วันเรียน <strong>${new Set(rows.map(x=>x.s.date)).size} วัน</strong></span><span>จำนวนคาบ <strong>${rows.length}</strong></span><span>เข้าร่วมจริง <strong>${esc(nice(actual))}</strong></span><span>ชั่วโมงที่บันทึก <strong>${esc(nice(total))}</strong></span></div><table><thead><tr><th>วันที่เรียน</th><th>เวลา</th><th>คอร์ส</th><th>ติวเตอร์</th><th>เข้าร่วมจริง</th><th>บันทึก</th></tr></thead><tbody>${rows.map(({a,s})=>`<tr><td>${esc(displayReportDate(s.date))}</td><td>${esc(s.start_time)}–${esc(s.end_time)}</td><td>${esc(courseTitle(a.course_id))}</td><td>${esc(s.tutor||'-')}</td><td>${esc(nice(a.actual_minutes))}</td><td>${esc(nice(a.deduct_minutes))}</td></tr>`).join('')}</tbody></table><footer>รายงานจากบันทึกที่ยืนยันแล้ว · ไม่รวมคาบที่ถูกยกเลิก · สร้างเมื่อ ${esc(displayReportDate(dateNow()))}</footer><p><button onclick="window.print()">พิมพ์ / Save as PDF</button></p></body></html>`;
 const win=window.open('','_blank');if(!win)throw Error('โปรดอนุญาตหน้าต่างใหม่ (Pop-up) เพื่อพิมพ์ PDF');win.document.write(report);win.document.close();win.focus();
}
function reports(){const approved=all('Sessions').filter(s=>s.status==='approved');const purchased=all('Ledger').filter(x=>x.type==='purchase').reduce((n,x)=>n+num(x.minutes),0);const deducted=Math.max(0,-all('Ledger').filter(x=>x.session_id&&['deduct','refund','adjustment'].includes(x.type)).reduce((n,x)=>n+num(x.minutes),0));const monthly=new Map();for(const s of approved){const month=(s.date||'').slice(0,7);monthly.set(month,(monthly.get(month)||0)+duration(s.start_time,s.end_time));}const bar=[...monthly].sort((a,b)=>a[0].localeCompare(b[0])).slice(-6),max=Math.max(1,...bar.map(x=>x[1]));return `${parentReportPanel()}${head('ANALYTICS / EXPORT','Reports & Summary','รายงานการสอน ชั่วโมงซื้อ และยอดคงเหลือ พร้อมส่งออกข้อมูล',`<div class="button-row">${btn('ตรวจสอบความถูกต้อง','integrity-check','soft')}${btn('สำรอง JSON','download-backup','soft')}${btn('⇩ Export CSV','export-csv','soft')}${btn('Print / Save PDF','print-report','primary')}</div>`)}<div class="stats"><div class="stat"><div class="mini">Approved Sessions</div><div class="big">${approved.length}</div></div><div class="stat"><div class="mini">Package Hours Sold</div><div class="big">${fmt(purchased)}</div></div><div class="stat"><div class="mini">Net Hours Deducted</div><div class="big">${fmt(deducted)}</div></div><div class="stat"><div class="mini">Students</div><div class="big">${all('Students').length}</div></div></div><div class="two-col"><section class="panel"><h2 class="panel-title">Teaching Sessions by Month</h2><p class="panel-desc">นับระยะเวลาคาบเรียน ไม่ใช่ยอดการหักรวมทุกคน</p>${bar.map(([month,mins])=>`<div class="bar-row"><span>${esc(month)}</span><div class="bar-bg"><div class="bar-value" style="width:${Math.round(mins/max*100)}%"></div></div><strong>${fmt(mins)}</strong></div>`).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</section><section class="panel"><h2 class="panel-title">Student Balances</h2>${all('Students').map(s=>`<div class="list-row"><div><strong style="font-size:12px">${esc(s.name)}</strong><div class="td-secondary">${liveCourses(s.id).length} active courses</div></div><strong class="amount">${fmt(currentStudentTotal(s.id))}</strong></div>`).join('')}</section></div><div class="note">รายงาน PDF ใช้หน้าต่างพิมพ์ของเบราว์เซอร์ (เลือก Save as PDF) และ CSV เปิดใน Excel ได้ รองรับข้อมูลภาษาไทยด้วย UTF-8 BOM</div>`;}
function openConnection(){modal('Google Sheets · ตั้งค่าการเชื่อมต่อ',`<div class="form"><div class="note">ตั้งค่าครั้งเดียว ระบบจดจำ Client ID และ Spreadsheet ID ที่ไม่ใช่รหัสลับบนเบราว์เซอร์นี้ และใช้ฐานข้อมูลจริงหลังลงชื่อเข้าใช้ Google</div><div class="field"><label for="connection-client">Google OAuth Web Client ID</label><input id="connection-client" type="text" autocomplete="off" spellcheck="false" value="${esc(config.googleClientId||'')}" placeholder="xxxxxxxx.apps.googleusercontent.com"></div><div class="field"><label for="connection-sheet">Google Spreadsheet ID หรือ URL</label><input id="connection-sheet" type="text" autocomplete="off" spellcheck="false" value="${esc(config.spreadsheetId||'')}" placeholder="จาก URL ของ Google Sheets"></div><div class="button-row"><button type="button" class="btn primary" data-action="save-connection">บันทึกการตั้งค่า</button><button type="button" class="btn" data-action="google-signin" ${!liveConfigured?'disabled':''}>${state.mode==='live'?'เชื่อมบัญชีใหม่':'เชื่อมบัญชี Google'}</button>${state.mode==='live'?'<button type="button" class="btn danger" data-action="disconnect">ออกจากระบบ</button>':''}</div><p class="helper">เก็บเฉพาะตัวระบุสาธารณะ ไม่จัดเก็บ Google Client Secret, รหัสผ่าน หรือ access token แบบถาวร · หลังสิทธิ์หมดอายุอาจต้องคลิก Google Sign-In อีกครั้งตามนโยบาย Google</p></div>`);}
function saveConnection(){const client=($('#connection-client')?.value||'').trim(),raw=($('#connection-sheet')?.value||'').trim();const id=(raw.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/)||[])[1]||raw;if(!/^[\w-]+\.apps\.googleusercontent\.com$/.test(client))throw Error('Client ID ไม่ถูกต้อง ควรลงท้าย .apps.googleusercontent.com');if(!/^[a-zA-Z0-9_-]{15,}$/.test(id))throw Error('Spreadsheet ID ไม่ถูกต้อง กรุณาวาง ID หรือ URL ของชีต');const changed=client!==config.googleClientId||id!==config.spreadsheetId;if(changed){clearGoogleSession();state.token='';state.tokenClient=null;store=new DemoStore();}config.googleClientId=client;config.spreadsheetId=id;liveConfigured=true;safeStorage('local','set',SETTINGS_KEY,JSON.stringify({googleClientId:client,spreadsheetId:id}));state.mode=changed?'needs_login':state.mode;closeModal();render();toast('บันทึกการตั้งค่า Google Sheets แล้ว');}
function googleLogin(){if(!liveConfigured){openConnection();return;}if(!window.google?.accounts?.oauth2)throw Error('โหลด Google Sign-In ไม่สำเร็จ ตรวจสอบอินเทอร์เน็ต / การปิดกั้นสคริปต์');if(!state.tokenClient){state.tokenClient=google.accounts.oauth2.initTokenClient({client_id:config.googleClientId,scope:'https://www.googleapis.com/auth/spreadsheets',callback:async resp=>{if(resp.error)return notice(resp.error);try{state.token=resp.access_token;store=new SheetsStore(state.token);const loaded=await store.load();state.data=loaded;state.mode='live';rememberGoogleSession(resp.access_token,resp.expires_in);closeModal();render();toast('เชื่อม Google Sheets สำเร็จ · รีเฟรชหน้านี้ได้โดยไม่ต้องเชื่อมใหม่จนกว่าเซสชันจะหมดอายุ');}catch(e){state.mode='needs_login';clearGoogleSession();state.token='';store=new DemoStore();render();notice(e);}},error_callback:e=>notice(e?.message||'Google Sign-In error')});}
// This action is launched by a real user click. GIS cannot refresh a browser token silently after expiry.
state.tokenClient.requestAccessToken({prompt:''});}
function disconnect(){const oldToken=state.token;state.token='';clearGoogleSession();state.mode=liveConfigured?'needs_login':'demo';store=new DemoStore();if(window.google?.accounts?.oauth2&&oldToken)google.accounts.oauth2.revoke(oldToken,()=>{});closeModal();if(state.mode==='needs_login')render();else reload().catch(notice);}
function openStudentForm(existing){const s=existing||{};modal(existing?'แก้ไขข้อมูลนักเรียน':'เพิ่มนักเรียน',`<form id="student-form" class="form"><input type="hidden" name="id" value="${esc(s.id||'')}"><div class="grid-2">${field('student-name','ชื่อเล่น / ชื่อที่ใช้แสดง','text',s.name||'','required')}${field('student-fullname','ชื่อ–นามสกุล','text',s.full_name||'')}</div><div class="grid-2">${field('student-school','โรงเรียน','text',s.school||'')}${selectField('student-grade','ระดับชั้น',gradeOptions(s.grade_level||''))}</div><div class="grid-2">${field('student-academic-year','ปีการศึกษา','text',s.academic_year||'')}${field('student-email','อีเมล','email',s.email||'')}</div>${field('student-aliases','ชื่อ Google Meet (คั่นด้วยจุลภาค)','text',s.aliases||'')}<div class="hourly-setting"><strong>เรียนรายชั่วโมง (ไม่บังคับ)</strong>${field('student-hourly-rate','ราคาเริ่มต้นต่อชั่วโมง (บาท)','number',s.hourly_rate_baht||'','min="0" step="0.01"')}<p class="helper">เมื่อเพิ่มนักเรียนใหม่และระบุราคามากกว่า 0 ระบบจะเปิดคอร์ส “เรียนรายชั่วโมง” รอบที่ 1 ให้ทันที · การแก้ราคาในโปรไฟล์จะไม่เปลี่ยนราคาของคอร์สเดิม</p></div><details class="student-schedule-optional"><summary>＋ กำหนดวันเรียน (ไม่บังคับ)</summary><p class="helper">เพิ่มลง Class Schedule และปรากฏในหน้าโปรไฟล์ทันที นักเรียนใหม่ก็เพิ่มตารางเรียนพร้อมกันได้</p><div class="grid-3">${field('student-sched-date','วันที่เรียน','date','')}${field('student-sched-start','เวลาเริ่ม','time','18:00')}${field('student-sched-end','เวลาสิ้นสุด','time','20:00')}</div><div class="grid-2">${field('student-sched-tutor','ติวเตอร์','text','Suthawarin')}${selectField('student-sched-repeat','การเรียนซ้ำ',`<option value="once">เฉพาะวันนี้</option><option value="weekly">ทุกสัปดาห์</option>`)}</div></details>${selectField('student-status','สถานะ',`<option value="active" ${s.status!=='archived'?'selected':''}>กำลังเรียน</option><option value="archived" ${s.status==='archived'?'selected':''}>พักเรียน</option>`)}<div class="field"><label>หมายเหตุ</label><textarea name="student-notes" rows="2">${esc(s.notes||'')}</textarea></div><div class="note">เมื่อแก้โรงเรียนหรือระดับชั้น ระบบจะเก็บประวัติการเปลี่ยนแปลง และไม่เปลี่ยนยอดชั่วโมงเรียน</div><button type="submit" class="btn primary">บันทึกนักเรียน</button></form>`);}
function gradeOptions(selected){const opts=['ป.1','ป.2','ป.3','ป.4','ป.5','ป.6','ม.1','ม.2','ม.3','ม.4','ม.5','ม.6','ปวช.1','ปวช.2','ปวช.3','ปวส.1','ปวส.2','มหาวิทยาลัย','อื่น ๆ'];if(selected&&!opts.includes(selected))opts.unshift(selected);return `<option value="">— ไม่ระบุ —</option>`+opts.map(g=>`<option value="${esc(g)}" ${g===selected?'selected':''}>${esc(g)}</option>`).join('');}
function openCourseForm(studentId=''){modal('สร้างคอร์สใหม่',`<form id="course-form" class="form">${selectField('course-student','นักเรียน',studentOptions(studentId),'required')}${field('course-title','ชื่อคอร์ส','text','Biology Olympiad','required')}${selectField('course-billing-mode','รูปแบบคอร์ส',`<option value="package">แพ็กเกจชั่วโมง (ซื้อชั่วโมงล่วงหน้า)</option><option value="hourly">เรียนรายชั่วโมง (ชำระหลังเรียน)</option>`)}<div class="grid-2">${field('course-date','วันเริ่มคอร์ส','date',dateNow(),'required')}${field('course-hours','จำนวนชั่วโมงสำหรับแพ็กเกจ','number','10','min="0" step="0.25"')}</div>${field('course-hourly-rate','ราคาเรียนรายชั่วโมง (บาท)','number',byId('Students',studentId)?.hourly_rate_baht||'','min="0" step="0.01"')}<p class="helper">หากเป็นรายชั่วโมง จะไม่หักจากกระเป๋าชั่วโมง แต่จะสร้างยอดรอชำระตามจำนวนชั่วโมงที่บันทึก</p>${selectField('course-group','เพิ่มนักเรียนเข้ากลุ่มเรียน (ไม่บังคับ)',`<option value="">คอร์สเดี่ยว / ยังไม่เลือกกลุ่ม</option>${all('Groups').map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('')}`)}<p class="helper">สร้างคอร์สใหม่แบบอิสระ หากต้องการต่อจากคอร์สเดิมให้กด “ต่อคอร์ส” ในโปรไฟล์นักเรียนเพื่อเก็บลำดับรอบ</p><button type="submit" class="btn primary">สร้างคอร์ส</button></form>`);updateCourseBillingFields();}
function updateCourseBillingFields(){const mode=$('#course-billing-mode')?.value||'package';const hourly=mode==='hourly';const hours=$('#course-hours')?.closest('.field'),rate=$('#course-hourly-rate')?.closest('.field');if(hours)hours.style.display=hourly?'none':'';if(rate)rate.style.display=hourly?'':'none';}
function openAssignExistingCourse(studentId){
 const student=byId('Students',studentId);if(!student)return;
 const catalog=[...new Map(all('Courses').filter(c=>c.status==='active').map(c=>[norm(c.title),c])).values()];
 const groupOptions=`<option value="">ไม่เพิ่มเข้ากลุ่ม</option>`+all('Groups').map(g=>`<option value="${esc(g.id)}">${esc(g.name)}</option>`).join('');
 modal('ลงคอร์สเพิ่มจากคอร์สที่มี · '+student.name,`<form id="assign-course-form" class="form"><input type="hidden" name="student_id" value="${esc(studentId)}"><div class="note">เลือกชื่อคอร์สที่มีอยู่เป็นต้นแบบ ระบบจะสร้างคอร์สของนักเรียนรายนี้แยกจากต้นแบบ (แพ็กเกจหรือรายชั่วโมงตามต้นแบบ) ไม่ใช้ยอดจากบัญชีคนอื่น</div>${selectField('template-course','คอร์สที่มีอยู่',`<option value="">เลือกคอร์สต้นแบบ</option>`+catalog.map(c=>`<option value="${esc(c.id)}">${esc(c.title)} · ${isHourly(c)?'รายชั่วโมง '+esc(baht(moneySatang(60,hourlyRate(c))))+'/ชม.':esc(fmt(c.purchased_minutes))}</option>`).join(''),'required')}<div class="grid-2">${field('assigned-date','วันเริ่มคอร์ส','date',dateNow(),'required')}${field('assigned-hours','จำนวนชั่วโมงที่ซื้อ','number','10','min="0.25" step="0.25" required')}</div>${selectField('assigned-group','เพิ่มเป็นสมาชิกกลุ่มเรียน (ไม่บังคับ)',groupOptions)}<button type="submit" class="btn primary">เพิ่มคอร์สและมอบหมายให้ ${esc(student.name)}</button></form>`);
}
async function saveAssignedCourse(form){const sid=inputVal(form,'student_id'),student=byId('Students',sid),template=byId('Courses',inputVal(form,'template-course')),date=inputVal(form,'assigned-date'),mins=Math.round(Number(inputVal(form,'assigned-hours'))*60),groupId=inputVal(form,'assigned-group');if(!student||!template||!dateValid(date)||(!isHourly(template)&&(!Number.isInteger(mins)||mins<=0||mins>100000)))throw Error('กรุณาตรวจสอบนักเรียน คอร์ส และชั่วโมง');if(groupId&&!byId('Groups',groupId))throw Error('ไม่พบกลุ่มเรียน');if(liveCourses(sid).some(c=>norm(c.title)===norm(template.title)))throw Error('นักเรียนมีคอร์สชื่อนี้ที่ยังใช้งานอยู่แล้ว กรุณาใช้ เติมชั่วโมง หรือ ต่อคอร์ส แทน');const title=template.title,cycle=Math.max(0,...coursesOf(sid).filter(c=>norm(c.title)===norm(title)).map(c=>num(c.cycle_no)))+1,id=uuid();const course={id,student_id:sid,title,cycle_no:cycle,start_date:date,purchased_minutes:isHourly(template)?0:mins,status:'active',previous_course_id:'',created_at:now(),closed_at:'',billing_mode:isHourly(template)?'hourly':'package',hourly_rate_baht:isHourly(template)?hourlyRate(template):0};const changes={add:{Courses:[course],Ledger:isHourly(template)?[]:[{id:uuid(),student_id:sid,course_id:id,session_id:'',type:'purchase',minutes:mins,note:'ลงคอร์สจากต้นแบบ '+template.id,created_at:now()}],Audit:[saveAudit('assigned_existing_course',id,{student:sid,template:template.id,groupId})]}};if(groupId){const g=byId('Groups',groupId);if(!membersOf(groupId).includes(sid)){changes.update={Groups:[{...g,member_ids:[...(g.member_ids||'').split('|').filter(Boolean),sid].join('|')}]};changes.add.GroupMemberships=[{id:uuid(),group_id:groupId,student_id:sid,joined_at:date,left_at:'',status:'active',created_at:now()}];}}await commit(changes);closeModal();state.studentId=sid;state.view='students';render();toast('เพิ่มคอร์สให้ '+student.name+' แล้ว พร้อมใช้รูปแบบการคิดเงินตามต้นแบบ');}
function openRenew(c){if(!c)return;if(isHourly(c)){const overdue=unpaidInvoices().filter(b=>b.course_id===c.id);modal('ต่อคอร์สรายชั่วโมง · '+studentName(c.student_id),`<form id="renew-form" class="form"><input type="hidden" name="old_id" value="${esc(c.id)}"><div class="note">${esc(c.title)} รอบ ${esc(c.cycle_no)} · ราคาปัจจุบัน ${esc(baht(moneySatang(60,hourlyRate(c))))}/ชม.<br>ยอดรอชำระ ${esc(baht(overdue.reduce((t,b)=>t+Number(b.amount_satang),0)))} จะคงอยู่ในประวัติรอบเก่า ไม่ย้ายยอดและไม่ลบทิ้ง</div>${field('renew-title','ชื่อคอร์สรอบใหม่','text',c.title,'required')}<div class="grid-2">${field('renew-date','วันเริ่มรอบใหม่','date',dateNow(),'required')}${field('renew-rate','ราคาต่อชั่วโมงรอบใหม่ (บาท)','number',hourlyRate(c),'min="0.01" step="0.01" required')}</div><div class="note">กดต่อแล้วสร้างคอร์สรอบใหม่ โดยใช้ Student ID เดิมและเก็บประวัติรอบก่อนทั้งหมด</div><button class="btn primary" type="submit">ยืนยันต่อคอร์สรายชั่วโมง</button></form>`);return;}const b=balance(c.id);modal('ต่อคอร์ส · '+studentName(c.student_id),`<form id="renew-form" class="form"><input type="hidden" name="old_id" value="${esc(c.id)}"><div class="note">คอร์สเดิม <b>${esc(c.title)} · รอบ ${esc(c.cycle_no)}</b> คงเหลือ ${fmt(b)}<br>เมื่อยืนยันจะสร้างรอบใหม่และซ่อนรอบเดิมจากหน้าปัจจุบัน โดยยังเปิดดูประวัติย้อนหลังได้</div>${field('renew-title','ชื่อคอร์สรอบใหม่','text',c.title,'required')}<div class="grid-2">${field('renew-date','วันที่เริ่มเรียน','date',dateNow(),'required')}${field('renew-hours','ชั่วโมงที่ซื้อเพิ่ม','number','10','step="0.25" min="0" required')}</div>${selectField('renew-policy','จัดการชั่วโมงคงเหลือของรอบเก่า',`<option value="transfer" ${coursePolicy(c.id)?.rollover_policy!=='keep'&&coursePolicy(c.id)?.rollover_policy!=='close'?'selected':''}>ยกยอด ${fmt(b)} ชั่วโมงไปคอร์สใหม่</option><option value="close" ${coursePolicy(c.id)?.rollover_policy==='close'?'selected':''}>ปิดยอดเก่าและเริ่มรอบใหม่</option><option value="keep" ${coursePolicy(c.id)?.rollover_policy==='keep'?'selected':''}>เก็บยอดในคอร์สเดิมให้ใช้ได้ต่อ (Held)</option>`)}<button class="btn primary" type="submit">ยืนยันการต่อคอร์ส</button></form>`);}
