 if(bill)update.Billing=[{...bill,status:(bill.status==='paid'||bill.status==='partial'||billPaidSatang(bill)>0)?'refund_due':'void',updated_at:now()}];if(!other.length)update.Sessions=[{...session,status:'cancelled'}];
