 await commit({update:{Attendance:[updated],...(oldBill?{Billing:[{...oldBill,minutes,amount_satang:moneySatang(minutes,oldBill.rate_baht),updated_at:now()}]}:{})},add:{Ledger:ledger,Audit:[saveAudit('attendance_edited',a.id,{old:a.deduct_minutes,new:minutes,previous_actual:a.actual_minutes,new_actual:minutes,old_join:a.join_time,old_leave:a.leave_time,new_join:join,new_leave:leave,reason})]}});
