async function onChange(e){const t=e.target;try{if(t.name==='member'&&t.closest('#group-form')){updateGroupMemberCount();return;}if(t.id==='leave-with-makeup'){const area=$('#leave-makeup-fields');if(area)area.hidden=!t.checked;return;}if(t.id==='manual-picker'){chooseManualStudent(t.value);return;}if(t.hasAttribute('data-manual-member')){const c=[...document.querySelectorAll('.manual-check')].find(x=>x.value===t.dataset.manualMember);if(c)c.checked=t.checked;return;}if(t.hasAttribute('data-manual-course')){const c=document.querySelector(`.manual-course[data-student="${CSS.escape(t.dataset.manualCourse)}"]`);if(c)c.value=t.value;return;}if(t.id==='system-verify-file'){await previewBackupFile(t.files?.[0]);t.value='';return;}if(t.id==='system-restore-demo'){await restoreDemoBackup(t.files?.[0]);return;}if(t.id==='excel-file'){const files=[...t.files];if(!files.length)return;await prepareImportBatch(files);return;}if(t.id==='leave-student'){const c=$('#leave-course');if(c)c.innerHTML=activeStudentCourseOptions(t.value);return;}if(t.id==='makeup-student'){const c=$('#makeup-course'),sched=$('#makeup-original-schedule');if(c)c.innerHTML=courseOptions(t.value);if(sched)sched.innerHTML=sourceScheduleOptions(t.value);return;}if(t.id==='course-billing-mode'){updateCourseBillingFields();return;}if(t.id==='course-student'){const s=byId('Students',t.value),rate=$('#course-hourly-rate');if(rate&&s?.hourly_rate_baht)rate.value=s.hourly_rate_baht;return;}if(t.id==='group_id'){const g=byId('Groups',t.value),ids=(g?.member_ids||'').split('|');document.querySelectorAll('.manual-check').forEach(check=>check.checked=ids.includes(check.value));const basis=$('#deduction_mode');if(basis&&ruleFor('group',t.value))basis.value=ruleFor('group',t.value).basis==='tutor'?'full':'full';return;}if(t.id==='summary-ack'){const button=$('#summary-confirm-btn');if(button)button.disabled=!t.checked;return;}if(t.hasAttribute('data-batch-select')){state.batchIncluded[Number(t.dataset.batchSelect)]=t.checked;return;}if(t.hasAttribute('data-review-check')){const sid=t.dataset.reviewCheck;state.reviewSelection=t.checked?[...new Set([...state.reviewSelection,sid])]:state.reviewSelection.filter(x=>x!==sid);const counter=$('#review-selected-count');if(counter)counter.textContent=state.reviewSelection.length;return;}if(t.id==='bulk-scope'){state.bulkScope=t.value;render();return;}if(t.id==='import-issue-only'){state.importIssueOnly=t.checked;render();return;}if(t.id==='bulk-class'){state.bulkClass=t.value;return;}if(t.id==='bulk-basis'){state.bulkBasis=t.value;render();return;}if(t.id==='bulk-minutes'){state.bulkMinutes=t.value;return;}if(t.id==='bulk-remember'){state.bulkRemember=t.checked;return;}if(['parent-report-student','parent-report-month','parent-report-course'].includes(t.id)){const k={'parent-report-student':'reportStudent','parent-report-month':'reportMonth','parent-report-course':'reportCourse'}[t.id];state[k]=t.value;if(t.id==='parent-report-student')state.reportCourse='';render();return;}if(t.id==='reconcile-month'){state.reconcileMonth=t.value;render();return;}if(t.id==='reconcile-student'){state.reconcileStudent=t.value;render();return;}if(t.id==='finance-month'){state.financeMonth=t.value;render();return;}if(t.id==='timeline-student'){state.timelineStudent=t.value;render();return;}if(t.id==='history-filter'){state.filter=t.value;render();return;}if(['history-from','history-to','history-student','history-group','history-course','history-tutor','history-status'].includes(t.id)){const key={'history-from':'historyFrom','history-to':'historyTo','history-student':'historyStudent','history-group':'historyGroup','history-course':'historyCourse','history-tutor':'historyTutor','history-status':'historyStatus'}[t.id];state[key]=t.value;render();return;}if(t.hasAttribute('data-import-date-file')){return;} // Apply only after clicking “บันทึกวันที่” for this file.
if(t.id==='student-grade-filter'){state.studentGradeFilter=t.value;render();return;}if(t.id==='student-status-filter'){state.studentStatusFilter=t.value;render();return;}const d=state.importDraft;if(!d)return;if(t.id==='import-type'){d.classType=t.value;d.groupId=t.value==='group'?d.groupId:'';d.people.forEach(p=>{p.manualMinutes=null;});render();return;}if(t.id==='import-split'){d.split=t.checked;d.people.forEach(p=>{p.classChoice=p.classChoice||'private';p.manualMinutes=null;});render();return;}if(t.id==='import-group'){d.groupId=t.value;d.basis=ruleFor('group',t.value)?.basis||d.basis;d.people.forEach(p=>{p.manualMinutes=null;if(p.studentId)p.courseId=proposedCourse(p.studentId,'group',t.value)?.id||'';});render();return;}if(t.id==='import-tutor'){d.tutorIndex=Number(t.value);d.people[d.tutorIndex].include=false;d.people.forEach(p=>p.manualMinutes=null);render();return;}if(t.id==='import-basis'){d.basis=t.value;d.people.forEach(p=>p.manualMinutes=null);render();return;}if(t.id==='import-source'){d.sourceIndex=Number(t.value);d.people.forEach(p=>p.manualMinutes=null);render();return;}let i;if(t.hasAttribute('data-import-include')){i=Number(t.dataset.importInclude);d.people[i].include=t.checked;render();return;}if(t.hasAttribute('data-import-student')){i=Number(t.dataset.importStudent);const p=d.people[i];p.studentId=t.value;p.courseId=proposedCourse(p.studentId,d.classType,d.groupId)?.id||'';p.remember=!!p.studentId;p.matchLevel=p.studentId?'match':'unknown';p.matchReason=p.studentId?'เลือกนักเรียนด้วยตนเอง':'';const propagated=p.studentId?propagateMeetMapping(d,p):0;render();if(propagated)toast('จดจำและจับคู่ชื่อ Meet นี้เพิ่ม '+propagated+' รายการในชุดไฟล์');return;}if(t.hasAttribute('data-import-remember')){i=Number(t.dataset.importRemember);d.people[i].remember=t.checked;return;}if(t.hasAttribute('data-import-class')){i=Number(t.dataset.importClass);const p=d.people[i];p.classChoice=t.value;p.courseId=proposedCourse(p.studentId,t.value==='private'?'private':'group',t.value)?.id||'';p.manualMinutes=null;render();return;}if(t.hasAttribute('data-import-course')){i=Number(t.dataset.importCourse);d.people[i].courseId=t.value;return;}if(t.hasAttribute('data-import-minutes')){i=Number(t.dataset.importMinutes);d.people[i].manualMinutes=t.value===''?NaN:Number(t.value);return;}}catch(err){notice(err);}}
function onInput(e){if(e.target.id==='group-member-search'){filterGroupMembers(e.target.value);return;}if(['edit-join','edit-leave'].includes(e.target.id)){updateEditAttendancePreview();return;}if(e.target.id==='manual-search'){const query=e.target.value.trim().toLocaleLowerCase();const picker=$('#manual-picker');if(picker){picker.querySelectorAll('option').forEach(o=>{if(!o.value)return;o.hidden=!!query&&!o.textContent.toLocaleLowerCase().includes(query);});}return;}if(e.target.id==='global-search-input')updateGlobalSearchResults(e.target.value);if(['class_start','class_end'].includes(e.target.id)||e.target.closest('[data-manual-session-row]')&&e.target.matches('input[type=time],input[type=date]'))manualRefreshRows();if(e.target.id==='student-search'){state.search=e.target.value;const pos=e.target.selectionStart;render();const next=$('#student-search');next?.focus();try{next.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='bulk-minutes'){state.bulkMinutes=e.target.value;}if(e.target.hasAttribute('data-import-minutes')){const d=state.importDraft;if(d)d.people[Number(e.target.dataset.importMinutes)].manualMinutes=e.target.value===''?NaN:Number(e.target.value);}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
function integrityIssues(){const issues=[];for(const c of all('Courses')){if(!isHourly(c)&&balance(c.id)<0)issues.push({kind:'balance',text:'ยอดติดลบ: '+studentName(c.student_id)+' / '+c.title});}
  const fingerprints=new Set();for(const x of all('Imports')){if(fingerprints.has(x.fingerprint))issues.push({kind:'duplicate',text:'พบไฟล์ Import ซ้ำ: '+x.filename});fingerprints.add(x.fingerprint);}
  for(const s of all('Sessions').filter(x=>x.status==='approved'))for(const a of all('Attendance').filter(x=>x.session_id===s.id&&x.status!=='cancelled')){const recorded=all('Ledger').filter(l=>l.session_id===s.id&&l.course_id===a.course_id&&l.type==='deduct').reduce((n,l)=>n+num(l.minutes),0);if(isHourly(byId('Courses',a.course_id))&&!billingOf(a.id))issues.push({kind:'billing',text:'คอร์สรายชั่วโมงไม่มีรายการค่าคาบ: '+studentName(a.student_id)+' '+s.date});if(!isHourly(byId('Courses',a.course_id))&&recorded===0&&num(a.deduct_minutes)>0)issues.push({kind:'ledger',text:'Approved โดยไม่พบ Ledger หักชั่วโมง: '+studentName(a.student_id)+' '+s.date});}
  for(const a of activeAliasRows()){const conflicts=activeAliasRows().filter(x=>x.id!==a.id&&x.student_id!==a.student_id&&((a.normalized_name&&a.normalized_name===x.normalized_name)||(a.normalized_email&&a.normalized_email===x.normalized_email)));if(conflicts.length)issues.push({kind:'identity',text:'ชื่อ Meet ขัดแย้ง: '+a.meet_name+' → '+studentName(a.student_id)});}
  for(const b of all('Billing')){const ps=billPayments(b.id),paid=ps.reduce((n,x)=>n+Number(x.amount_satang),0);if(paid>Number(b.amount_satang))issues.push({kind:'overpaid',text:'จ่ายเงินเกินยอด '+studentName(b.student_id)});if(b.status==='paid'&&ps.length&&paid<Number(b.amount_satang))issues.push({kind:'partial',text:'สถานะปิดยอดไม่ตรงกับยอดจ่าย '+studentName(b.student_id)});}
  for(const m of all('MakeupCredits').filter(x=>x.status==='completed')){if(!m.linked_attendance_id||byId('Attendance',m.linked_attendance_id)?.status!=='approved')issues.push({kind:'makeup',text:'คาบชดเชยเสร็จแล้วแต่ไม่พบคาบเรียนที่บันทึก '+studentName(m.student_id)});}
  for(const l of all('LeaveRecords')){if(l.end_date&&l.end_date<l.start_date)issues.push({kind:'leave',text:'วันลาเริ่ม/สิ้นสุดไม่ถูกต้อง '+studentName(l.student_id)});}
  return issues;}
function openIntegrity(){const issues=integrityIssues();modal('Data Integrity · ตรวจสอบฐานข้อมูล',`<div class="note">ตรวจสอบยอดติดลบ รายงานนำเข้าซ้ำ การขาด Ledger และชื่อ Meet ขัดแย้ง · ผลนี้เป็นการตรวจในฝั่งเบราว์เซอร์ ไม่ใช่การรับรองธุรกรรมจากเซิร์ฟเวอร์</div><div class="metric-strip mt20"><div><small>รายการที่พบ</small><b>${issues.length}</b></div><div><small>สถานะ</small><b>${issues.length?'Needs Review':'No issues detected'}</b></div></div><div class="mt20">${issues.map(x=>`<div class="note warn mt12"><strong>${esc(x.kind)}</strong> · ${esc(x.text)}</div>`).join('')||'<div class="note">ไม่พบความผิดปกติตามกฎที่ตรวจสอบในเวอร์ชันนี้</div>'}</div>`, '',true);}
/* v2.3 operations — leave / make-up / teaching journal / reconciliation / secure exports. */
const activeLeave=(studentId,date,courseId='')=>all('LeaveRecords').find(l=>l.student_id===studentId&&l.status!=='cancelled'&&l.start_date<=date&&(!l.end_date||l.end_date>=date)&&(!l.course_id||(!!courseId&&l.course_id===courseId)));
const scheduleException=(scheduleId,date,studentId='')=>all('ScheduleExceptions').find(x=>x.schedule_id===scheduleId&&x.occurrence_date===date&&(x.student_id===''||x.student_id===studentId));
const billPayments=id=>all('Payments').filter(x=>x.billing_id===id);
const billPaidSatang=b=>{const paid=billPayments(b.id).reduce((n,p)=>n+Number(p.amount_satang),0);return paid||(['paid','refund_due','refunded'].includes(b.status)&&b.paid_at?Number(b.amount_satang):0);};
const billDueSatang=b=>Math.max(0,Number(b.amount_satang)-billPaidSatang(b));
const outstandingBills=()=>all('Billing').filter(b=>['unpaid','partial'].includes(b.status)&&billDueSatang(b)>0);
const formOptions=(items,selected='',empty='ทั้งหมด')=>`<option value="">${esc(empty)}</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('');
const activeStudentCourseOptions=(studentId,selected='')=>formOptions(coursesOf(studentId).map(x=>({id:x.id,name:x.title+' · รอบ '+x.cycle_no})),selected,'ทุกคอร์ส');
const thaiShort=d=>dateValid(d)?displayReportDate(d):'ไม่กำหนด';
function notificationItems(){const today=dateNow(),next=addCalendarDays(today,7),out=[];
 for(const l of all('LeaveRecords').filter(x=>x.status==='active'&&x.expected_return&&x.expected_return<=next)){out.push({kind:'leave',title:studentName(l.student_id)+' · ใกล้กลับมาเรียน',detail:'คาดกลับ '+thaiShort(l.expected_return),student_id:l.student_id});}
 for(const m of all('MakeupCredits').filter(x=>['pending','scheduled'].includes(x.status))){if(!m.scheduled_date||m.scheduled_date<=next)out.push({kind:'makeup',title:studentName(m.student_id)+' · เรียนชดเชย',detail:m.scheduled_date?'นัด '+thaiShort(m.scheduled_date):'ยังไม่ได้นัดวัน',student_id:m.student_id});}
 for(const c of all('Courses').filter(x=>x.status==='active'&&!isHourly(x)&&balance(x.id)<=120))out.push({kind:'low',title:studentName(c.student_id)+' · คอร์สใกล้หมด',detail:c.title+' เหลือ '+nice(balance(c.id)),student_id:c.student_id});
 const old=outstandingBills().filter(b=>{const s=byId('Sessions',b.session_id);return s?.date<=addCalendarDays(today,-7);});for(const b of old)out.push({kind:'bill',title:studentName(b.student_id)+' · ยอดค้างชำระ',detail:baht(billDueSatang(b)),student_id:b.student_id});
 for(const sc of scheduleOccurrences(today,today)){const ids=sc.group_id?membersOf(sc.group_id):[sc.student_id];const recorded=all('Sessions').some(se=>se.date===today&&se.status==='approved'&&activeAttendanceRows(se.id).some(a=>ids.includes(a.student_id))&&Math.abs(minutesOf(se.start_time)-minutesOf(sc.start_time))<=30);if(!recorded)out.push({kind:'schedule',title:(sc.group_id?byId('Groups',sc.group_id)?.name:studentName(sc.student_id))+' · ยังไม่ลงชั่วโมง',detail:'ตามตารางวันนี้ '+sc.start_time+'–'+sc.end_time,student_id:ids[0]||''});}
 return out;
}
function notificationsPanel(){const items=notificationItems();return `${head('REMINDERS / ACTIONS','ศูนย์แจ้งเตือน','รายการติดตามจากข้อมูลในระบบ ณ เวลาที่เปิดหน้านี้ · ไม่ใช่การส่งข้อความอัตโนมัติ',btn('ตรวจข้อมูล','integrity-check','soft'))}<section class="panel"><div class="panel-head"><h3 class="panel-title">รายการต้องติดตาม ${items.length}</h3></div>${items.map(x=>`<div class="ops-line"><div><strong>${esc(x.title)}</strong><small>${esc(x.detail)}</small></div>${btnInline('ดูนักเรียน','student-detail',x.student_id)}</div>`).join('')||'<p class="empty">ยังไม่มีรายการที่ต้องติดตาม</p>'}</section>`;}
function leavePanel(){const rows=[...all('LeaveRecords')].sort((a,b)=>String(b.start_date).localeCompare(a.start_date));const makeups=[...all('MakeupCredits')].sort((a,b)=>String(b.created_at).localeCompare(a.created_at));return `${head('LEAVE / MAKE-UP','ลาหยุดและเรียนชดเชย','ระบุวันลา พักการเรียน วันที่คาดกลับ และนัดชดเชยเชื่อมกับคาบต้นฉบับ',`<div class="button-row">${btn('＋ แจ้งลา / พักเรียน','add-leave','primary')}${btn('＋ นัดชดเชย','add-makeup','soft')}</div>`)}<div class="metric-strip"><div><small>พักเรียน / ลาอยู่</small><b>${rows.filter(x=>x.status==='active').length}</b></div><div><small>คาบชดเชยรอนัด</small><b>${makeups.filter(x=>x.status==='pending').length}</b></div><div><small>นัดชดเชยแล้ว</small><b>${makeups.filter(x=>x.status==='scheduled').length}</b></div><div><small>ชดเชยเสร็จ</small><b>${makeups.filter(x=>x.status==='completed').length}</b></div></div><section class="panel mt20"><div class="panel-head"><h2 class="panel-title">วันลาและพักการเรียน</h2></div><div class="table-wrap"><table><thead><tr><th>นักเรียน</th><th>ประเภท</th><th>เริ่ม–สิ้นสุด</th><th>คาดกลับ</th><th>คอร์ส</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(studentName(l.student_id))}</td><td>${pill(l.kind==='pause'?'พักการเรียน':'ลาหยุด',l.kind==='pause'?'gold':'blue')}</td><td>${thaiShort(l.start_date)} – ${l.end_date?thaiShort(l.end_date):'ยังไม่กำหนด'}</td><td>${thaiShort(l.expected_return)}</td><td>${l.course_id?esc(courseTitle(l.course_id)):'ทุกคอร์ส'}</td><td>${pill(l.status==='active'?'กำลังลา / พัก':l.status==='ended'?'กลับมาเรียนแล้ว':'ยกเลิก',l.status==='active'?'gold':'green')}</td><td>${l.status==='active'?btnInline('ยืนยันกลับมา','end-leave',l.id):''}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">ยังไม่มีประวัติการลา</td></tr>'}</tbody></table></div></section><section class="panel mt20"><div class="panel-head"><h2 class="panel-title">สิทธิ์และคาบเรียนชดเชย</h2></div><div class="table-wrap"><table><thead><tr><th>นักเรียน / คอร์ส</th><th>คาบต้นฉบับ</th><th>ชดเชย</th><th>ระยะเวลา</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody>${makeups.map(m=>`<tr><td><strong>${esc(studentName(m.student_id))}</strong><small>${esc(courseTitle(m.course_id))}</small></td><td>${thaiShort(m.origin_date)}</td><td>${m.scheduled_date?thaiShort(m.scheduled_date)+' '+esc(m.start_time)+'–'+esc(m.end_time):'ยังไม่ได้นัด'}</td><td>${nice(m.planned_minutes)}</td><td>${pill(m.status==='completed'?'เรียนชดเชยแล้ว':m.status==='scheduled'?'นัดแล้ว':m.status==='cancelled'?'ยกเลิก':'รอนัด',m.status==='completed'?'green':m.status==='scheduled'?'blue':'gold')}</td><td>${m.status==='pending'||m.status==='scheduled'?(m.status==='scheduled'?btnInline('บันทึกเวลา','record-makeup',m.id)+' ':'')+btnInline('กำหนดวัน','plan-makeup',m.id)+' '+btnInline('ยกเลิก','cancel-makeup',m.id):m.status==='completed'&&m.linked_attendance_id?btnInline('ประวัติคาบ','detail-makeup',m.id):'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีคาบชดเชย</td></tr>'}</tbody></table></div></section>`;}
function openLeaveForm(studentId=''){modal('แจ้งลา / พักการเรียน',`<form class="form" id="leave-form">${selectField('leave-student','นักเรียน',studentOptions(studentId),'required')}${selectField('leave-course','คอร์สที่ได้รับผลกระทบ',activeStudentCourseOptions(studentId))}${selectField('leave-kind','ประเภท',`<option value="leave">ลาหยุด</option><option value="pause">พักการเรียนต่อเนื่อง</option>`)}<div class="grid-2">${field('leave-start','เริ่มลา','date',dateNow(),'required')}${field('leave-end','สิ้นสุด (ว่างได้เมื่อยังไม่ทราบ)','date','')}</div>${field('leave-return','คาดว่าจะกลับมาเรียน','date','')}${field('leave-reason','หมายเหตุ (ไม่ต้องระบุข้อมูลสุขภาพส่วนตัว)','text','')}<div class="leave-makeup-area"><label class="leave-makeup-label"><input type="checkbox" id="leave-with-makeup" name="leave-with-makeup"> นัดเรียนชดเชยพร้อมกับการลา</label><div id="leave-makeup-fields" hidden>${field('leave-makeup-date','วันที่ชดเชย','date','') }<div class="grid-2">${field('leave-makeup-start','เวลาเริ่ม','time','18:00')}${field('leave-makeup-end','เวลาสิ้นสุด','time','19:00')}</div>${field('leave-makeup-tutor','ติวเตอร์','text','Suthawarin')}<p class="helper">สร้างสิทธิ์ชดเชยและนัดหมายในขั้นตอนเดียว ยังไม่หักชั่วโมงหรือเรียกเก็บเงิน ต้องระบุคอร์สด้วย</p></div></div><div class="note">การแจ้งลาไม่หักหรือคืนชั่วโมงอัตโนมัติ และไม่เปลี่ยนสถานะกลับมาเรียนเมื่อถึงวันที่คาดไว้ กรุณายืนยันอีกครั้งเมื่อกลับมา · ถ้าเลือกลาเฉพาะคอร์ส ระบบจะแจ้งสถานะไว้ แต่ไม่ซ่อนคาบอัตโนมัติ เพราะตารางเดิมไม่มีรหัสคอร์ส</div><button class="btn primary" type="submit">บันทึกวันลา / พัก</button></form>`);}
async function saveLeave(f){const studentId=inputVal(f,'leave-student'),courseId=inputVal(f,'leave-course'),start=inputVal(f,'leave-start'),end=inputVal(f,'leave-end'),returned=inputVal(f,'leave-return'),withMakeup=!!f.querySelector('#leave-with-makeup')?.checked;if(!byId('Students',studentId)||!dateValid(start)||end&&(!dateValid(end)||end<start)||returned&&(!dateValid(returned)||returned<start))throw Error('กรุณาตรวจสอบนักเรียนและช่วงวันลา');if(courseId&&byId('Courses',courseId)?.student_id!==studentId)throw Error('คอร์สไม่ตรงนักเรียน');const item={id:uuid(),student_id:studentId,course_id:courseId,kind:inputVal(f,'leave-kind'),start_date:start,end_date:end,expected_return:returned,reason:inputVal(f,'leave-reason'),status:'active',created_at:now(),updated_at:now()};const adds={LeaveRecords:[item],Audit:[saveAudit('leave_created',item.id,{studentId,start,end})]};if(withMakeup){if(!courseId)throw Error('กรุณาเลือกคอร์สสำหรับเรียนชดเชย');if(inputVal(f,'leave-kind')!=='leave')throw Error('การพักเรียนต่อเนื่องให้สร้างนัดชดเชยแยกเมื่อยืนยันวันกลับมา');if(end&&end!==start)throw Error('หากลาหลายวัน โปรดสร้างชดเชยแต่ละคาบแยกกัน');const day=inputVal(f,'leave-makeup-date'),st=inputVal(f,'leave-makeup-start'),et=inputVal(f,'leave-makeup-end'),tutor=inputVal(f,'leave-makeup-tutor'),minutes=duration(st,et);if(!dateValid(day)||!minutes||minutes<1||minutes>720||day===start)throw Error('กรุณาตรวจวันที่และช่วงเวลาเรียนชดเชย');if(activeLeave(studentId,day,courseId)||day>=start&&(!end||day<=end))throw Error('วันชดเชยยังอยู่ในช่วงลา/พักเรียน');if(all('MakeupCredits').some(m=>m.student_id===studentId&&m.course_id===courseId&&m.origin_date===start&&m.status!=='cancelled'))throw Error('มีสิทธิ์ชดเชยจากคาบนี้แล้ว');if(all('Attendance').some(a=>a.student_id===studentId&&a.status==='approved'&&byId('Sessions',a.session_id)?.date===start))throw Error('คาบต้นฉบับมีบันทึกเรียนจริงแล้ว');if(plannedOverlaps(studentId,day,st,et,tutor))throw Error('เวลาชดเชยซ้อนตารางอื่น');const m={id:uuid(),student_id:studentId,course_id:courseId,origin_schedule_id:'',origin_date:start,planned_minutes:minutes,scheduled_date:day,start_time:st,end_time:et,tutor,status:'scheduled',linked_attendance_id:'',notes:'นัดพร้อมแจ้งลา · '+(item.reason||''),created_at:now(),updated_at:now()};adds.MakeupCredits=[m];adds.Audit.push(saveAudit('makeup_scheduled_with_leave',m.id,{studentId,start,day,minutes}));}await commit({add:adds});closeModal();toast(withMakeup?'บันทึกการลาและนัดชดเชยแล้ว (ยังไม่หักชั่วโมง)':'บันทึกการลา/พักเรียนแล้ว · ยังไม่หักชั่วโมง');}

function sourceScheduleOptions(studentId){const plans=all('Schedules').filter(s=>s.status==='active'&&(!studentId||s.student_id===studentId||s.group_id&&membersOf(s.group_id).includes(studentId)));return formOptions(plans.map(x=>({id:x.id,name:(x.group_id?byId('Groups',x.group_id)?.name||'กลุ่ม':studentName(x.student_id))+' · '+x.date+' '+x.start_time})), '', 'เลือกคาบต้นฉบับ (ถ้ามี)');}
function openMakeupForm(studentId='',scheduleId='',originDate=''){modal('สร้างสิทธิ์เรียนชดเชย',`<form id="makeup-form" class="form">${selectField('makeup-student','นักเรียน',studentOptions(studentId),'required')}${selectField('makeup-course','คอร์ส',courseOptions(studentId),'required')}${selectField('makeup-original-schedule','ตารางคาบเดิม',sourceScheduleOptions(studentId))}${field('makeup-original-date','วันที่คาบต้นฉบับ','date',originDate||dateNow(),'required')}${field('makeup-minutes','ระยะเวลาที่มีสิทธิ์ชดเชย (นาที)','number','60','min="1" max="720" step="1" required')}${field('makeup-note','เหตุผล / ข้อตกลงการชดเชย','text','','required')}<div class="note">เลือกคาบที่ยังไม่ได้บันทึกเป็นการเรียนจริงเท่านั้น ระบบจะไม่ตัดชั่วโมงจนกว่าจะลงเวลาเรียนชดเชยจริง และไม่สร้างสิทธิ์ซ้ำสำหรับนักเรียน/คาบเดิม</div><button class="btn primary" type="submit">สร้างสิทธิ์ชดเชย (ยังไม่ตัดชั่วโมง)</button></form>`);}
async function saveMakeup(f){const studentId=inputVal(f,'makeup-student'),courseId=inputVal(f,'makeup-course'),origin=inputVal(f,'makeup-original-date'),schedId=inputVal(f,'makeup-original-schedule'),minutes=Number(inputVal(f,'makeup-minutes'));if(!byId('Students',studentId)||byId('Courses',courseId)?.student_id!==studentId||!dateValid(origin)||!Number.isInteger(minutes)||minutes<=0||minutes>720)throw Error('ตรวจสอบนักเรียน คอร์ส วันที่และนาที');const source=byId('Schedules',schedId);if(schedId&&(!source||!(source.student_id===studentId||source.group_id&&membersOf(source.group_id).includes(studentId))))throw Error('คาบต้นฉบับไม่ตรงนักเรียน');if(all('Attendance').some(a=>a.student_id===studentId&&a.status==='approved'&&byId('Sessions',a.session_id)?.date===origin&&(!schedId||source.start_time===byId('Sessions',a.session_id)?.start_time)))throw Error('คาบต้นฉบับมีการบันทึกเรียนจริงแล้ว: โปรดตรวจสถานะก่อนสร้างสิทธิ์ชดเชย');if(all('MakeupCredits').some(m=>m.student_id===studentId&&m.course_id===courseId&&m.origin_date===origin&&m.origin_schedule_id===schedId&&m.status!=='cancelled'))throw Error('มีสิทธิ์ชดเชยจากคาบนี้แล้ว');const m={id:uuid(),student_id:studentId,course_id:courseId,origin_schedule_id:schedId,origin_date:origin,planned_minutes:minutes,scheduled_date:'',start_time:'',end_time:'',tutor:source?.tutor||'',status:'pending',linked_attendance_id:'',notes:inputVal(f,'makeup-note'),created_at:now(),updated_at:now()};await commit({add:{MakeupCredits:[m],Audit:[saveAudit('makeup_credit_created',m.id,{studentId,origin,minutes})]}});closeModal();toast('สร้างสิทธิ์ชดเชยแล้ว · ยังไม่ตัดชั่วโมง');}
function plannedOverlaps(studentId,date,start,end,tutor,ignoreMakeup=''){const overlap=(a,b)=>{const x=minutesOf(a.start_time),y=minutesOf(b.start_time);return Number.isFinite(x)&&Number.isFinite(y)&&Math.max(x,y)<Math.min(x+duration(a.start_time,a.end_time),y+duration(b.start_time,b.end_time));};const candidate={start_time:start,end_time:end};const plans=scheduleOccurrences(date,date).filter(x=>!activeLeave(x.student_id,date)&&!scheduleException(x.id,date,x.student_id));for(const x of plans){if(overlap(candidate,x)&&(x.student_id===studentId||x.group_id&&membersOf(x.group_id).includes(studentId)||tutor&&x.tutor&&norm(tutor)===norm(x.tutor)))return x;}for(const m of all('MakeupCredits').filter(x=>x.id!==ignoreMakeup&&x.status==='scheduled'&&x.scheduled_date===date)){if(overlap(candidate,{start_time:m.start_time,end_time:m.end_time})&&(m.student_id===studentId||tutor&&m.tutor&&norm(tutor)===norm(m.tutor)))return m;}return null;}
function openMakeupPlan(id){const m=byId('MakeupCredits',id);if(!m||!['pending','scheduled'].includes(m.status))return;modal('นัดวันเรียนชดเชย · '+studentName(m.student_id),`<form class="form" id="makeup-plan-form"><input type="hidden" name="makeup-id" value="${esc(id)}"><div class="note">จากวันที่ ${thaiShort(m.origin_date)} · สิทธิ์ ${nice(m.planned_minutes)} · ${esc(courseTitle(m.course_id))}</div>${field('makeup-date','วันชดเชย','date',m.scheduled_date||dateNow(),'required')}<div class="grid-2">${field('makeup-start','เริ่ม','time',m.start_time||'18:00','required')}${field('makeup-end','สิ้นสุด','time',m.end_time||'19:00','required')}</div>${field('makeup-tutor','ติวเตอร์','text',m.tutor||'Suthawarin','required')}<button class="btn primary" type="submit">ยืนยันนัดชดเชย</button></form>`);}
async function saveMakeupPlan(f){const m=byId('MakeupCredits',inputVal(f,'makeup-id')),date=inputVal(f,'makeup-date'),start=inputVal(f,'makeup-start'),end=inputVal(f,'makeup-end'),tutor=inputVal(f,'makeup-tutor');if(!m||!['pending','scheduled'].includes(m.status)||!dateValid(date)||duration(start,end)<=0||duration(start,end)>720||duration(start,end)>Number(m.planned_minutes))throw Error('เวลาเรียนชดเชยต้องถูกต้องและไม่เกินสิทธิ์เดิม');if(activeLeave(m.student_id,date,m.course_id))throw Error('นักเรียนอยู่ในช่วงลาหยุด/พักการเรียน');const collision=plannedOverlaps(m.student_id,date,start,end,tutor,m.id);if(collision)throw Error('ตารางซ้อนกับคาบอื่น กรุณาเลือกวันหรือเวลาใหม่');await commit({update:{MakeupCredits:[{...m,scheduled_date:date,start_time:start,end_time:end,tutor,status:'scheduled',updated_at:now()}]},add:{Audit:[saveAudit('makeup_scheduled',m.id,{date,start,end})]}});closeModal();toast('นัดเรียนชดเชยแล้ว · รอลงเวลาจริง');}
async function cancelMakeup(id){const m=byId('MakeupCredits',id);if(!m||m.status==='completed'||m.status==='cancelled')return;if(!confirm('ยกเลิกสิทธิ์/นัดชดเชยนี้? การยกเลิกไม่เปลี่ยนชั่วโมงเรียน'))return;await commit({update:{MakeupCredits:[{...m,status:'cancelled',updated_at:now()}]},add:{Audit:[saveAudit('makeup_cancelled',id,{})]}});toast('ยกเลิกนัดชดเชยแล้ว');}
function makeupRecord(m){state.recordMakeupId=m.id;go('manual');const f=$('#manual-form');if(!f)return;$('#class_date').value=m.scheduled_date;$('#class_start').value=m.start_time;$('#class_end').value=m.end_time;if($('#tutor'))$('#tutor').value=m.tutor||'Suthawarin';manualSelectChoice('s:'+m.student_id);const check=f.querySelector(`input[name="participant"][value="${CSS.escape(m.student_id)}"]`);f.querySelectorAll('input[name="participant"]').forEach(c=>c.checked=c===check);const course=f.querySelector(`select.manual-course[data-student="${CSS.escape(m.student_id)}"]`);if(course)course.value=m.course_id;const visibleCourse=$(`[data-manual-course="${CSS.escape(m.student_id)}"]`);if(visibleCourse)visibleCourse.value=m.course_id;$('#class_start')?.dispatchEvent(new Event('input',{bubbles:true}));toast('เลือกคาบชดเชยแล้ว · ตรวจสอบเวลาและยืนยันบันทึก');}
function leaveStudentCard(studentId){const leaves=all('LeaveRecords').filter(l=>l.student_id===studentId).sort((a,b)=>String(b.start_date).localeCompare(a.start_date));const makeup=all('MakeupCredits').filter(m=>m.student_id===studentId);return `<section class="ops-student-block"><div class="panel-head"><h3 class="panel-title">Leave & Make-up · การลาและเรียนชดเชย</h3><div class="button-row">${btnInline('＋ แจ้งลา','leave-for-student',studentId)} ${btnInline('＋ ชดเชย','makeup-for-student',studentId)} ${btnInline('Export Calendar','student-ics',studentId)}</div></div>${leaves.slice(0,3).map(l=>`<div class="ops-line"><div><strong>${l.kind==='pause'?'พักการเรียน':'ลาหยุด'} · ${thaiShort(l.start_date)} – ${l.end_date?thaiShort(l.end_date):'ไม่กำหนด'}</strong><small>คาดกลับ ${thaiShort(l.expected_return)} · ${l.status==='active'?'รอยืนยันกลับ':'กลับแล้ว'}</small></div>${pill(l.status==='active'?'พัก/ลา':'สิ้นสุด',l.status==='active'?'gold':'green')}</div>`).join('')}${makeup.filter(x=>x.status!=='cancelled').map(m=>`<div class="ops-line"><div><strong>ชดเชยจาก ${thaiShort(m.origin_date)}</strong><small>${nice(m.planned_minutes)} · ${m.scheduled_date?thaiShort(m.scheduled_date):'รอนัดวัน'} · ${m.status}</small></div>${m.status==='scheduled'?btnInline('บันทึกเวลา','record-makeup',m.id):''}</div>`).join('')}${!leaves.length&&!makeup.length?'<div class="note">ยังไม่มีการลา พักเรียน หรือสิทธิ์ชดเชย</div>':''}</section>`;}
function openExceptionForm(scheduleId,date,studentId=''){const sc=byId('Schedules',scheduleId);if(!sc)throw Error('เลือกคาบในตารางก่อน');modal('ปรับเฉพาะคาบ · '+thaiShort(date),`<form class="form" id="exception-form"><input type="hidden" name="ex-schedule" value="${esc(scheduleId)}"><input type="hidden" name="ex-date" value="${esc(date)}">${sc.group_id?selectField('ex-student','ขอบเขตที่ได้รับผลกระทบ',`<option value="">ทั้งกลุ่ม</option>${membersOf(sc.group_id).map(id=>`<option value="${esc(id)}" ${id===studentId?'selected':''}>เฉพาะ ${esc(studentName(id))}</option>`).join('')}`):`<input type="hidden" name="ex-student" value="">`} ${selectField('ex-kind','การดำเนินการ',`<option value="cancelled">ลาหยุด / งดคาบนี้</option><option value="rescheduled">เลื่อนคาบนี้เท่านั้น</option>`)}${field('ex-new-date','วันที่ใหม่ (กรณีเลื่อน)','date','')}${field('ex-new-start','เวลาใหม่ เริ่ม','time',sc.start_time)}${field('ex-new-end','เวลาใหม่ จบ','time',sc.end_time)}${field('ex-reason','หมายเหตุ','text','','required')}<div class="note">การเลื่อนคาบทำให้คาบเดิมไม่แสดง แต่ไม่ยกเลิกชุดตารางประจำรายสัปดาห์หรือแก้ยอดชั่วโมงที่บันทึกแล้ว</div><button class="btn primary" type="submit">บันทึกการเปลี่ยนแปลงเฉพาะคาบ</button></form>`);}
async function saveException(f){const id=inputVal(f,'ex-schedule'),date=inputVal(f,'ex-date'),studentId=inputVal(f,'ex-student'),kind=inputVal(f,'ex-kind'),newDate=inputVal(f,'ex-new-date'),start=inputVal(f,'ex-new-start'),end=inputVal(f,'ex-new-end');const sc=byId('Schedules',id);if(!sc||!dateValid(date)||kind==='rescheduled'&&(!dateValid(newDate)||duration(start,end)<=0||duration(start,end)>720))throw Error('เลือกคาบและวันที่ใหม่ให้ถูกต้อง');if(studentId&&!membersOf(sc.group_id).includes(studentId))throw Error('นักเรียนไม่ใช่สมาชิกกลุ่ม');if(all('ScheduleExceptions').some(x=>x.schedule_id===id&&x.occurrence_date===date&&x.student_id===studentId))throw Error('คาบนี้เคยมีการปรับแล้ว โปรดตรวจสอบก่อน');if(kind==='rescheduled'){const students=studentId?[studentId]:sc.group_id?membersOf(sc.group_id):[sc.student_id];for(const sid of students){if(activeLeave(sid,newDate))throw Error('นักเรียนอยู่ในช่วงลาพัก');if(plannedOverlaps(sid,newDate,start,end,sc.tutor))throw Error('เวลาใหม่ซ้อนตารางเรียน');}}const x={id:uuid(),schedule_id:id,occurrence_date:date,student_id:studentId,kind,replacement_date:kind==='rescheduled'?newDate:'',start_time:kind==='rescheduled'?start:'',end_time:kind==='rescheduled'?end:'',reason:inputVal(f,'ex-reason'),created_at:now(),updated_at:now()};await commit({add:{ScheduleExceptions:[x],Audit:[saveAudit('schedule_exception',x.id,{id,date,kind,studentId})]}});closeModal();toast('บันทึกการปรับเฉพาะคาบเรียบร้อย');}
function openLessonJournal(attendanceId){const a=byId('Attendance',attendanceId);if(!a)return;const existing=all('LessonNotes').find(x=>x.attendance_id===a.id),s=byId('Sessions',a.session_id);modal('Lesson Journal · '+studentName(a.student_id),`<form class="form" id="lesson-form"><input type="hidden" name="lesson-att" value="${esc(a.id)}"><div class="note">${thaiShort(s?.date)} · ${esc(courseTitle(a.course_id))} · ${nice(a.deduct_minutes)}</div>${field('lesson-title','เรื่องที่เรียน','text',existing?.title||'','required')}<div class="field"><label for="lesson-homework">การบ้าน / แบบฝึกหัด</label><textarea id="lesson-homework" name="lesson-homework" rows="3">${esc(existing?.homework||'')}</textarea></div><div class="field"><label for="lesson-follow">หัวข้อที่จะติดตามคาบหน้า</label><textarea id="lesson-follow" name="lesson-follow" rows="3">${esc(existing?.follow_up||'')}</textarea></div><button class="btn primary" type="submit">บันทึกสมุดการสอน</button></form>`);}
async function saveLesson(f){const aid=inputVal(f,'lesson-att'),a=byId('Attendance',aid),title=inputVal(f,'lesson-title');if(!a||!title)throw Error('กรุณาเลือกคาบและหัวข้อที่สอน');const old=all('LessonNotes').find(x=>x.attendance_id===aid);const item={id:old?.id||uuid(),attendance_id:aid,student_id:a.student_id,course_id:a.course_id,title,homework:inputVal(f,'lesson-homework'),follow_up:inputVal(f,'lesson-follow'),created_at:old?.created_at||now(),updated_at:now()};await commit({[old?'update':'add']:{LessonNotes:[item]},add:old?{Audit:[saveAudit('lesson_updated',item.id,{aid})]}:{LessonNotes:[item],Audit:[saveAudit('lesson_created',item.id,{aid})]}});closeModal();toast('บันทึกเนื้อหาการสอนแล้ว');}
function teachingJournal(){const items=all('Attendance').filter(x=>x.status==='approved').map(a=>({a,s:byId('Sessions',a.session_id),n:all('LessonNotes').find(x=>x.attendance_id===a.id)})).filter(x=>x.s?.status==='approved').sort((x,y)=>y.s.date.localeCompare(x.s.date));return `${head('TEACHING / NOTES','สมุดบันทึกการสอน','เก็บหัวข้อเรียน การบ้าน และการติดตามตามคาบที่บันทึกจริง')}<section class="panel"><div class="table-wrap"><table><thead><tr><th>วันที่</th><th>นักเรียน</th><th>คอร์ส</th><th>หัวข้อ</th><th>การบ้าน</th><th>จัดการ</th></tr></thead><tbody>${items.map(({a,s,n})=>`<tr><td>${thaiShort(s.date)}</td><td>${esc(studentName(a.student_id))}</td><td>${esc(courseTitle(a.course_id))}</td><td>${esc(n?.title||'ยังไม่บันทึก')}</td><td>${esc(n?.homework||'—')}</td><td>${btnInline(n?'แก้ไข':'＋ บันทึก','lesson-note',a.id)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">ยังไม่มีคาบเรียน</td></tr>'}</tbody></table></div></section>`;}
function openPartialPayment(ids){const bs=ids.map(id=>byId('Billing',id)).filter(b=>b&&['unpaid','partial'].includes(b.status)&&billDueSatang(b)>0);if(!bs.length)throw Error('ไม่มีรายการรอชำระ');const due=bs.reduce((n,b)=>n+billDueSatang(b),0);modal('รับชำระค่าคาบ '+bs.length+' รายการ',`<form id="partial-payment-form" class="form"><input type="hidden" name="bill-ids" value="${esc(bs.map(b=>b.id).join('|'))}"><div class="note">${bs.map(b=>`${esc(studentName(b.student_id))} · ${esc(baht(billDueSatang(b)))}`).join('<br>')}</div>${field('pay-amount','ยอดรับเงินจริง (บาท)','number',(due/100).toFixed(2),`required min="0.01" max="${(due/100).toFixed(2)}" step="0.01"`)}${selectField('pay-method','วิธีชำระ',`<option value="transfer">โอนเงิน</option><option value="cash">เงินสด</option><option value="other">อื่น ๆ</option>`)}${field('pay-date','วันที่รับเงิน','date',dateNow(),'required')}${field('pay-note','เลขอ้างอิง / หมายเหตุ','text','')}<label class="summary-agree"><input type="checkbox" name="confirm-paid" required><span>ได้รับเงินจริงตามยอดด้านบนแล้ว</span></label><div class="note">กรณีชำระหลายคาบ ระบบจะจัดสรรยอดจากคาบเก่าที่สุดก่อน สามารถรับบางส่วนได้</div><button class="btn primary" type="submit">บันทึกการรับเงินจริง</button></form>`);}
async function savePartialPayment(f){const ids=inputVal(f,'bill-ids').split('|').filter(Boolean);const bs=ids.map(id=>byId('Billing',id)).filter(Boolean).sort((a,b)=>String(byId('Sessions',a.session_id)?.date||'').localeCompare(String(byId('Sessions',b.session_id)?.date||'')));let remaining=Math.round(Number(inputVal(f,'pay-amount'))*100),due=bs.reduce((n,b)=>n+billDueSatang(b),0);if(!Number.isSafeInteger(remaining)||remaining<=0||remaining>due||!dateValid(inputVal(f,'pay-date'))||!f.querySelector('[name="confirm-paid"]')?.checked||bs.length!==ids.length)throw Error('ตรวจยอดเงิน วันที่ และยืนยันการรับเงินจริง');const updated=[],payments=[];for(const b of bs){if(!['unpaid','partial'].includes(b.status))throw Error('สถานะค่าคาบเปลี่ยนแล้ว กรุณารีเฟรช');const amount=Math.min(remaining,billDueSatang(b));if(!amount)continue;remaining-=amount;const paid= billPaidSatang(b)+amount;payments.push({id:uuid(),billing_id:b.id,amount_satang:amount,method:inputVal(f,'pay-method'),paid_on:inputVal(f,'pay-date'),note:inputVal(f,'pay-note'),created_at:now()});updated.push({...b,status:paid>=Number(b.amount_satang)?'paid':'partial',paid_at:paid>=Number(b.amount_satang)?now():'',payment_method:inputVal(f,'pay-method'),updated_at:now()});}await commit({update:{Billing:updated},add:{Payments:payments,Audit:[saveAudit('payment_received',ids.join('|'),{amount_satang:payments.reduce((n,p)=>n+p.amount_satang,0),count:payments.length})]}});closeModal();toast('บันทึกรับชำระแล้ว ยอดค้างอัปเดตตามเงินจริง');}
function partialPaymentPanel(){const bills=outstandingBills().sort((a,b)=>String(byId('Sessions',a.session_id)?.date||'').localeCompare(String(byId('Sessions',b.session_id)?.date||'')));const due=bills.reduce((n,b)=>n+billDueSatang(b),0);return `<section class="panel mt20"><div class="panel-head"><div><h2 class="panel-title">Payment Center · รับชำระบางส่วนหรือหลายคาบ</h2><p class="panel-desc">เลือกรายการก่อนรับเงิน · ยอดค้างคำนวณจากประวัติรับเงินจริง</p></div>${btn('รับชำระรายการที่เลือก','pay-selected','primary')}</div><div class="metric-strip"><div><small>ยอดค้างสุทธิ</small><b>${baht(due)}</b></div><div><small>รายการค้าง</small><b>${bills.length}</b></div><div><small>ชำระบางส่วน</small><b>${bills.filter(b=>b.status==='partial').length}</b></div></div><div class="table-wrap mt20"><table><thead><tr><th>เลือก</th><th>วันที่</th><th>นักเรียน</th><th>ราคาเต็ม</th><th>จ่ายแล้ว</th><th>ยังค้าง</th><th>รับเงิน</th></tr></thead><tbody>${bills.map(b=>`<tr><td><input type="checkbox" data-pay-select="${esc(b.id)}" aria-label="เลือกรายการ ${esc(studentName(b.student_id))}"></td><td>${thaiShort(byId('Sessions',b.session_id)?.date)}</td><td>${esc(studentName(b.student_id))}</td><td>${baht(b.amount_satang)}</td><td>${baht(billPaidSatang(b))}</td><td><strong>${baht(billDueSatang(b))}</strong></td><td>${btnInline('รับชำระ','pay-single',b.id)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">ไม่มีค่าคาบค้างชำระ</td></tr>'}</tbody></table></div></section>`;}
function billingPaymentHistory(){const rows=all('Payments').slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));return `<section class="panel mt20"><div class="panel-head"><h3 class="panel-title">ประวัติการรับเงินจริง</h3></div><div class="table-wrap"><table><thead><tr><th>วันที่รับ</th><th>นักเรียน</th><th>ยอดรับ</th><th>วิธี</th><th>หมายเหตุ</th></tr></thead><tbody>${rows.map(p=>{const b=byId('Billing',p.billing_id);return `<tr><td>${thaiShort(p.paid_on)}</td><td>${esc(studentName(b?.student_id))}</td><td>${baht(p.amount_satang)}</td><td>${esc(p.method)}</td><td>${esc(p.note)}</td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">ยังไม่มีรายการรับเงินในระบบใหม่นี้</td></tr>'}</tbody></table></div></section>`;}
function safeDownload(filename,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function backupExport(){if(!confirm('ไฟล์สำรองมีข้อมูลนักเรียนและประวัติการชำระเงิน โปรดเก็บไว้ในที่ปลอดภัยและห้ามเผยแพร่สาธารณะ ยืนยันดาวน์โหลด?'))return;const payload={format:'AreWarin-TutorOS-backup-v2.4',created_at:now(),sheets:structuredClone(state.data)};safeDownload('AreWarin-PRIVATE-backup-'+dateNow()+'.json',JSON.stringify(payload,null,2),'application/json;charset=utf-8');toast('ส่งออกข้อมูลสำรองแล้ว โปรดเก็บไฟล์ให้ปลอดภัย');}
function safeICS(v){return String(v??'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');}
function icsTimestamp(date,time){return date.replaceAll('-','')+'T'+time.replace(':','')+'00';}
function exportICS(studentId=''){const start=dateNow(),to=addCalendarDays(start,90),events=studentId?personalCalendarItems(studentId,start,to).filter(x=>x.source!=='recorded'):calendarEntries(start,to).filter(x=>x.source!=='recorded');const unique=new Set(),textEvents=events.filter(e=>{const k=e.id+'|'+(e.on_date||e.date)+'|'+e.start_time+'|'+e.end_time;if(unique.has(k))return false;unique.add(k);return true;}).map(e=>{const date=e.on_date||e.date,starttime=e.start_time||e.start,endtime=e.end_time||e.end; if(!dateValid(date)||!starttime||!endtime)return '';const summary=studentId?'AreWarin · '+(e.label||'คาบเรียน'):'AreWarin · '+(e.group_id?byId('Groups',e.group_id)?.name:studentName(e.student_id));return ['BEGIN:VEVENT','UID:'+safeICS(e.id+'-'+date+'@arewarin.tutor'),'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;TZID=Asia/Bangkok:'+icsTimestamp(date,starttime),'DTEND;TZID=Asia/Bangkok:'+icsTimestamp(date,endtime),'SUMMARY:'+safeICS(summary),'DESCRIPTION:'+safeICS('กำหนดเวลาเรียนล่วงหน้า ไม่ใช่ยืนยันชั่วโมงที่สอนจริง'),'END:VEVENT'].join('\r\n');}).filter(Boolean);const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AreWarin Tutor OS//Calendar 2.4//TH','CALSCALE:GREGORIAN','X-WR-TIMEZONE:Asia/Bangkok',...textEvents,'END:VCALENDAR'].join('\r\n');safeDownload('AreWarin-Calendar-'+(studentId||'all')+'.ics',text,'text/calendar;charset=utf-8');toast('ส่งออกปฏิทิน '+textEvents.length+' คาบ (ล่วงหน้า 90 วัน)');}
function addMeetWarnings(d){if(!d)return '';const fragmented=d.people.filter((p,i)=>i!==d.tutorIndex&&(p.segments||[]).length>1);const changed=d.people.filter((p,i)=>i!==d.tutorIndex&&p.include&&Number(p.manualMinutes??calculatedImport(d,p))!==Number(p.actual));return `<div class="ops-meet-check"><strong>Smart Attendance Check</strong><p class="helper">รวมช่วงเข้า–ออกที่ทับซ้อนก่อนคำนวณ ไม่เพิ่มเวลาซ้ำ และแจ้งรายการที่ควรตรวจ</p>${fragmented.length?`<div class="note warn">ผู้เรียนเข้า–ออกหลายรอบ ${fragmented.length} ราย: ${esc(fragmented.map(p=>p.name+' ('+p.segments.length+' ช่วง)').join(', '))} · ตรวจเวลาจริงก่อนบันทึก</div>`:'<div class="note">ไม่พบผู้เรียนที่มีช่วงเข้าร่วมหลายช่วงในไฟล์นี้</div>'}${changed.length?`<div class="note warn mt12">นาทีที่เสนอให้ตัดต่างจากเวลาเข้าร่วมจริง ${changed.length} ราย · โปรดตรวจ Final Review</div>`:''}</div>`;}
async function parentPdfDirect(){const rows=parentReportRows();if(!rows.length)throw Error('ไม่มีคาบในเงื่อนไขรายงาน');if(!window.html2canvas||!window.jspdf?.jsPDF){parentPdf();toast('ไม่สามารถโหลดตัวสร้าง PDF โดยตรง จึงเปิดหน้าพิมพ์แทน');return;}const student=byId('Students',state.reportStudent);if(!student)throw Error('โปรดเลือกนักเรียน');showBusy('กำลังจัดหน้ารายงาน PDF…');const {jsPDF}=window.jspdf,doc=new jsPDF({unit:'mm',format:'a4',compress:true});const container=document.createElement('div');container.style.cssText='position:fixed;left:-12000px;top:0;width:760px;background:white;color:#18392d;font-family:"Noto Sans Thai",sans-serif;z-index:-1;padding:0';document.body.appendChild(container);const chunkSize=10,pages=[];try{await document.fonts?.ready;for(let i=0;i<rows.length;i+=chunkSize){const slice=rows.slice(i,i+chunkSize);container.innerHTML=`<section style="padding:36px 30px;min-height:970px;box-sizing:border-box"><div style="font-size:12px;letter-spacing:3px;color:#28644b;font-weight:700">AREWARIN TUTOR · STUDY REPORT</div><h1 style="font-size:26px;color:#174d3c;margin:16px 0">รายงานเวลาเรียนรายบุคคล</h1><div style="font-size:14px;margin:10px 0">นักเรียน: <b>${esc(student.name)}</b> · เดือน ${esc(state.reportMonth)} · ${esc(state.reportCourse?courseTitle(state.reportCourse):'ทุกคอร์ส')}</div>${i===0?`<div style="background:#f3f7f2;padding:16px;font-size:13px">จำนวนคาบ <b>${rows.length}</b> · เวลาจริง <b>${nice(rows.reduce((n,x)=>n+num(x.a.actual_minutes),0))}</b> · เวลาที่บันทึก <b>${nice(rows.reduce((n,x)=>n+num(x.a.deduct_minutes),0))}</b></div>`:''}<table style="width:100%;border-collapse:collapse;margin-top:18px;font-size:12px"><thead><tr style="background:#eef4ef"><th style="text-align:left;padding:10px">วันที่</th><th>เวลา</th><th>คอร์ส</th><th>เข้าจริง</th><th>บันทึก</th><th>สถานะ</th></tr></thead><tbody>${slice.map(({a,s})=>`<tr><td style="padding:10px 5px;border-bottom:1px solid #ddd">${thaiShort(s.date)}</td><td>${esc(s.start_time)}–${esc(s.end_time)}</td><td>${esc(courseTitle(a.course_id))}</td><td>${nice(a.actual_minutes)}</td><td>${nice(a.deduct_minutes)}</td><td>${billingOf(a.id)?esc(billingOf(a.id).status==='paid'?'ชำระแล้ว': 'ยังค้าง'): 'แพ็กเกจ'}</td></tr>`).join('')}</tbody></table><p style="color:#64796d;font-size:11px;margin-top:24px">คาบที่ยกเลิกไม่รวมในรายงาน · ข้อมูลจากระบบ ณ ${thaiShort(dateNow())}</p><p style="color:#64796d;font-size:11px;margin-top:12px">AreWarin Tutor · หน้า ${Math.floor(i/chunkSize)+1} / ${Math.ceil(rows.length/chunkSize)}</p></section>`;const canvas=await window.html2canvas(container,{backgroundColor:'#ffffff',scale:1.5,useCORS:false,logging:false});if(pages.length)doc.addPage();doc.addImage(canvas.toDataURL('image/jpeg',0.88),'JPEG',0,0,210,Math.min(297,canvas.height/canvas.width*210));pages.push(true);}doc.save('AreWarin-ParentReport-'+state.reportMonth+'-'+student.id.slice(0,8)+'.pdf');}finally{container.remove();hideBusy();}}

/* Calendar detail side panel: keeps the calendar visible while reviewing events. */
function closeCalendarDrawer(){const root=$('#calendar-drawer-root');if(root)root.innerHTML='';}
function openCalendarDrawer(raw){const [kind,id,date,studentId='']=String(raw||'').split('|');const root=$('#calendar-drawer-root');if(!root)return;let html='';
 if(kind==='recorded'){
  const sess=byId('Sessions',id);if(!sess)throw Error('ไม่พบคาบเรียนที่เลือก');const aa=activeAttendanceRows(id).filter(a=>!studentId||a.student_id===studentId);
  html=`<div class="calendar-drawer-date">${thaiShort(sess.date)} · ${esc(sess.start_time)}–${esc(sess.end_time)}</div><h3>บันทึกเวลาเรียนแล้ว</h3><p class="helper">${esc(sess.mode==='excel'?'นำเข้า Google Meet':'ลงเวลาเรียนเอง')} · ${esc(sess.tutor||'—')}</p><div class="calendar-drawer-list">${aa.map(a=>`<div class="ops-line"><div><strong>${esc(studentName(a.student_id))}</strong><small>${esc(courseTitle(a.course_id))} · เข้าจริง ${nice(a.actual_minutes)} · บันทึก ${nice(a.deduct_minutes)}</small></div>${btnInline('Lesson Journal','lesson-note',a.id)}</div>`).join('')}</div><div class="button-row mt20">${btnInline('ดู Session Details','session-detail',id)}</div>`;
 }else if(kind==='makeup'){
  const m=byId('MakeupCredits',id);if(!m)return;html=`<div class="calendar-drawer-date">${thaiShort(m.scheduled_date)}</div><h3>คาบเรียนชดเชย</h3><p>${esc(studentName(m.student_id))} · ${esc(courseTitle(m.course_id))}</p><p class="helper">นัด ${esc(m.start_time)}–${esc(m.end_time)} · สิทธิ์ ${nice(m.planned_minutes)} · จากคาบ ${thaiShort(m.origin_date)}</p><div class="button-row mt20">${btnInline('บันทึกเวลา','record-makeup',id)} ${btnInline('ปรับวันนัด','plan-makeup',id)}</div>`;
 }else if(kind==='leave'){
  const l=byId('LeaveRecords',id);if(!l)return;html=`<div class="calendar-drawer-date">${thaiShort(l.start_date)} – ${l.end_date?thaiShort(l.end_date):'ไม่กำหนด'}</div><h3>${l.kind==='pause'?'พักการเรียน':'ลาหยุด'}</h3><p>${esc(studentName(l.student_id))}</p><p class="helper">คาดกลับ ${thaiShort(l.expected_return)} · ${esc(l.reason||'ไม่มีหมายเหตุ')}</p>${l.status==='active'?btnInline('ยืนยันกลับมาเรียน','end-leave',id):''}`;
 }else{
  const sc=byId('Schedules',id);if(!sc)return;html=`<div class="calendar-drawer-date">${thaiShort(date)} · ${esc(sc.start_time)}–${esc(sc.end_time)}</div><h3>${sc.group_id?'เรียนกลุ่ม':'เรียนเดี่ยว'}</h3><p>${esc(sc.group_id?byId('Groups',sc.group_id)?.name:studentName(sc.student_id))}</p><p class="helper">${esc(sc.tutor||'—')} · ${esc(sc.repeat_rule==='weekly'?'ทุกสัปดาห์':'เฉพาะครั้ง')} · ยังไม่ใช่เวลาเรียนจริง</p><div class="button-row mt20">${btnInline('แก้ไขชุดตาราง','edit-schedule',sc.id)} ${btnInline('เลื่อน/งดเฉพาะวัน','schedule-exception',sc.id+'|'+date)} ${btnInline('บันทึกเวลา','record-from-schedule',sc.id+'|'+date)}</div>`;
 }
 root.innerHTML=`<div class="calendar-drawer-backdrop" data-action="close-drawer"></div><aside class="calendar-drawer" role="dialog" aria-modal="false" aria-label="รายละเอียดคาบเรียน"><div class="calendar-drawer-top"><span>CALENDAR / DETAILS</span><button type="button" data-action="close-drawer" aria-label="ปิดแผงรายละเอียด">×</button></div><div class="calendar-drawer-body">${html}</div></aside>`;
}

/* System Health & Backup Center. Live restoration intentionally uses Google Drive copies, not browser-wide destructive writes. */
function systemPage(){const problems=integrityIssues(),audits=all('Audit').slice().sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));return `${head('SECURITY / DATA','System Health & Backup','ตรวจสอบข้อมูล สำรองไฟล์ส่วนตัว และแนวทางกู้คืนโดยไม่เขียนทับฐานข้อมูลจริงโดยพลการ')}<div class="metric-strip"><div><small>ชีตฐานข้อมูล</small><b>${Object.keys(SCHEMA).length}</b></div><div><small>ตรวจพบข้อควรทบทวน</small><b>${problems.length}</b></div><div><small>ประวัติการแก้ไข</small><b>${audits.length}</b></div><div><small>การเชื่อมต่อ</small><b>${state.mode==='live'?'Google Sheets':state.mode==='demo'?'Demo':'ยังไม่เชื่อม'}</b></div></div><div class="two-col mt20"><section class="panel"><div class="panel-head"><h2 class="panel-title">Health Checks</h2>${btn('ตรวจสอบละเอียด','integrity-check','small soft')}</div><p class="helper">ตรวจยอดชั่วโมงติดลบ รายงานนำเข้าซ้ำ Attendance ที่ขาด Ledger/Billing ชื่อ Meet ที่ซ้ำ และสถานะค่าคาบชดเชย</p>${problems.slice(0,8).map(x=>`<div class="note warn mt12"><strong>${esc(x.kind)}</strong> · ${esc(x.text)}</div>`).join('')||'<div class="note">ไม่พบปัญหาตามกฎที่มีในเบราว์เซอร์ (ไม่ได้รับรองความถูกต้องแบบธุรกรรมพร้อมกัน)</div>'}</section><section class="panel"><div class="panel-head"><h2 class="panel-title">Private Data Backup</h2></div><p>ข้อมูลสำรองเป็น JSON ครบทั้ง 20 ชีต สำหรับเก็บส่วนตัวเท่านั้น</p>${btn('⇩ ดาวน์โหลดข้อมูลสำรองส่วนตัว','download-backup','primary')}<div class="note warn mt12">ข้อมูลสำรองมีข้อมูลนักเรียนและการเงิน ห้ามวางบน GitHub Pages, ที่เก็บสาธารณะ หรือส่งให้บุคคลที่ไม่เกี่ยวข้อง</div></section></div><section class="panel mt20"><h2 class="panel-title">Google Sheets · Daily Backup & Restore</h2><div class="ops-steps"><div><b>01</b><span>เปิด Google Sheets → Extensions → Apps Script</span></div><div><b>02</b><span>รัน <code>setupTutorOS()</code> เมื่ออัปเกรดเวอร์ชันนี้</span></div><div><b>03</b><span>เลือกเปิดการสำรองอัตโนมัติโดยรัน <code>installDailyBackup()</code> และอนุญาตสิทธิ์ Google Drive</span></div><div><b>04</b><span>หากต้องการกู้คืน ให้เปิดไฟล์สำรอง Google Drive ตรวจสอบวันและรายการก่อนใช้งานสำเนานั้นแทนไฟล์เดิม และตั้ง Spreadsheet ID ตามที่ต้องการ</span></div></div><div class="note mt12">ระบบนี้ไม่เปลี่ยน Spreadsheet ID หรือกู้คืนทับข้อมูลจริงโดยอัตโนมัติ เพื่อป้องกันข้อมูลนักเรียนหาย · ควรเก็บไฟล์สำรองหลายรุ่นและตรวจพื้นที่ Google Drive</div></section>${state.mode==='demo'?`<section class="panel mt20"><h2 class="panel-title">Demo Only · ทดลองกู้คืน JSON</h2><p class="helper">ใช้สำหรับทดสอบบนเครื่องนี้เท่านั้น ไม่แก้ Google Sheets จริง การนำเข้าจะแทนข้อมูล Demo ปัจจุบัน</p><div class="field"><label for="system-restore-demo">เลือกไฟล์ Backup JSON ส่วนตัว</label><input id="system-restore-demo" type="file" accept=".json,application/json"></div></section>`:''}<section class="panel mt20"><h2 class="panel-title">Recent Audit</h2>${audits.slice(0,12).map(a=>`<div class="ops-line"><div><strong>${esc(a.action)}</strong><small>${esc(a.created_at.slice(0,19).replace('T',' '))} · ${esc(a.target_id||'—')}</small></div></div>`).join('')||'<p class="helper">ยังไม่มีบันทึก Audit</p>'}</section>${reliabilityExtras()}`;}
async function restoreDemoBackup(file){if(state.mode!=='demo')throw Error('กู้คืนผ่าน JSON ได้เฉพาะ Demo เท่านั้น');if(!file)return;if(file.size>10*1024*1024)throw Error('ไฟล์มีขนาดเกิน 10 MB');const raw=JSON.parse(await file.text());if(!['AreWarin-TutorOS-backup-v2.3','AreWarin-TutorOS-backup-v2.4'].includes(raw.format)||!raw.sheets||Object.keys(SCHEMA).some(k=>!Array.isArray(raw.sheets[k])))throw Error('รูปแบบไฟล์ไม่ใช่สำรอง AreWarin v2.3 ที่สมบูรณ์');for(const key of Object.keys(SCHEMA)){const seen=new Set();for(const row of raw.sheets[key]){if(typeof row!=='object'||!row||!row.id||seen.has(row.id))throw Error('พบข้อมูล '+key+' ไม่ถูกต้องหรือรหัสซ้ำ');seen.add(row.id);}}if(!confirm('การกู้คืนจะเขียนทับข้อมูล DEMO ทั้งหมดบนเครื่องนี้ ต้องการดำเนินการจริงหรือไม่?'))return;localStorage.setItem('awtutor_v1_demo',JSON.stringify(raw.sheets));state.data=normalizeData(raw.sheets);state.view='system';render();toast('กู้คืน Demo จาก JSON แล้ว · ไม่เปลี่ยน Google Sheets');}

// Class Schedule v1.5: same occurrences feed the weekly calendar and the table.
// Work only with UTC date math on yyyy-mm-dd strings, so the user's local DST/timezone cannot shift weekdays.
function addCalendarDays(date,delta){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+delta);return d.toISOString().slice(0,10);}
function calendarWeekStart(date){const day=new Date(date+'T12:00:00Z').getUTCDay();return addCalendarDays(date,-((day+6)%7));}
function thaiScheduleDate(date,options={day:'numeric',month:'short'}){return new Date(date+'T12:00:00Z').toLocaleDateString('th-TH',{timeZone:'UTC',...options});}
function scheduleOccurrences(from,to){
 const result=[];
 for(const entry of all('Schedules').filter(e=>e.status==='active'&&e.date&&e.date<=to)){
  if(entry.repeat_rule==='weekly'){
   const weekday=new Date(entry.date+'T12:00:00Z').getUTCDay();
   for(let ds=from;ds<=to;ds=addCalendarDays(ds,1)){
    if(ds>=entry.date&&new Date(ds+'T12:00:00Z').getUTCDay()===weekday)result.push({...entry,on_date:ds});
   }
  }else if(entry.date>=from&&entry.date<=to)result.push({...entry,on_date:entry.date});
 }
 const adjusted=[];
 for(const x of result){const ex=scheduleException(x.id,x.on_date,'');if(ex&&ex.student_id===''){if(ex.kind==='rescheduled'&&ex.replacement_date>=from&&ex.replacement_date<=to)adjusted.push({...x,on_date:ex.replacement_date,start_time:ex.start_time,end_time:ex.end_time,source:'rescheduled',notes:ex.reason});continue;}
 if(x.student_id&&activeLeave(x.student_id,x.on_date))continue;adjusted.push(x);}
 for(const ex of all('ScheduleExceptions').filter(ex=>!ex.student_id&&ex.kind==='rescheduled'&&ex.replacement_date>=from&&ex.replacement_date<=to&&!(ex.occurrence_date>=from&&ex.occurrence_date<=to))){const orig=byId('Schedules',ex.schedule_id);if(orig&&orig.status==='active')adjusted.push({...orig,on_date:ex.replacement_date,start_time:ex.start_time,end_time:ex.end_time,notes:ex.reason,source:'rescheduled'});}
 return adjusted.sort((a,b)=>(a.on_date+a.start_time+a.id).localeCompare(b.on_date+b.start_time+b.id));
}
// The calendar includes both planned meetings and saved attendance dates.
// Planned events are the source of the "today" dashboard; recorded-only dates
// are added to the calendar without pretending that they were scheduled.
function calendarEntries(from,to){
 const planned=scheduleOccurrences(from,to),result=[...planned];
 for(const m of all('MakeupCredits').filter(m=>m.status==='scheduled'&&m.scheduled_date>=from&&m.scheduled_date<=to))result.push({id:m.id,on_date:m.scheduled_date,date:m.scheduled_date,start_time:m.start_time,end_time:m.end_time,student_id:m.student_id,group_id:'',tutor:m.tutor,repeat_rule:'once',status:'active',source:'makeup',notes:'เรียนชดเชยจาก '+thaiShort(m.origin_date)});
 for(const session of all('Sessions').filter(x=>x.status!=='cancelled'&&x.date>=from&&x.date<=to)){
   const attendees=activeAttendanceRows(session.id),studentId=attendees.length===1?attendees[0].student_id:'',groupId=session.group_id||'';
   const alreadyPlanned=planned.some(x=>x.on_date===session.date&&x.start_time===session.start_time&&x.end_time===session.end_time&&(groupId?x.group_id===groupId:(x.student_id&&x.student_id===studentId)));
   if(!alreadyPlanned)result.push({id:session.id,on_date:session.date,date:session.date,start_time:session.start_time,end_time:session.end_time,student_id:studentId,group_id:groupId,tutor:session.tutor,repeat_rule:'once',status:session.status,notes:'บันทึกจาก '+(session.mode==='excel'?'Google Meet':'Record Hours'),source:'recorded',student_label:attendees.map(a=>studentName(a.student_id)).join(', ')||'คาบเรียน'});
 }
 return result.sort((a,b)=>(a.on_date+a.start_time+a.id).localeCompare(b.on_date+b.start_time+b.id));
}
function scheduledDates(){const today=dateNow();return scheduleOccurrences(today,addCalendarDays(today,20));}
function schedule(){
 const weekStart=state.scheduleWeek||calendarWeekStart(dateNow());
 const weekEnd=addCalendarDays(weekStart,6);
 const items=calendarEntries(weekStart,weekEnd);
 const isTable=state.scheduleLayout==='table';
 const countPrivate=items.filter(x=>!x.group_id).length;
 const countGroup=items.length-countPrivate;
 const days=['จันทร์','อังคาร','พุธ','พฤหัสบดี','ศุกร์','เสาร์','อาทิตย์'];
 const label=x=>x.source==='recorded'?x.student_label:x.group_id?byId('Groups',x.group_id)?.name||'ไม่พบกลุ่ม':studentName(x.student_id);
 const controls=`<div class="schedule-controls" role="toolbar" aria-label="มุมมองตารางเรียน"><div class="schedule-view-switch" role="group" aria-label="เลือกมุมมอง"><button type="button" data-action="schedule-view-week" class="${!isTable?'selected':''}" aria-pressed="${!isTable}">▦ รายสัปดาห์</button><button type="button" data-action="schedule-view-table" class="${isTable?'selected':''}" aria-pressed="${isTable}">☷ ตารางรายการ</button></div><div class="schedule-navigation"><button type="button" class="schedule-nav" data-action="schedule-prev-week" aria-label="สัปดาห์ก่อนหน้า">‹</button><strong>${esc(thaiScheduleDate(weekStart))} – ${esc(thaiScheduleDate(weekEnd,{day:'numeric',month:'short',year:'numeric'}))}</strong><button type="button" class="schedule-nav" data-action="schedule-next-week" aria-label="สัปดาห์ถัดไป">›</button><button type="button" class="btn small soft" data-action="schedule-current-week">สัปดาห์นี้</button></div></div>`;
 const stats=`<div class="schedule-stats"><span>${pill(items.length+' คาบ','green')}</span><span class="schedule-key"><i class="schedule-dot private"></i> เรียนเดี่ยว ${countPrivate}</span><span class="schedule-key"><i class="schedule-dot group"></i> เรียนกลุ่ม ${countGroup}</span></div>`;
 const week=`<div class="schedule-week-scroll" tabindex="0" aria-label="ตารางเรียน 7 วัน เลื่อนซ้ายขวาได้"><div class="schedule-week-grid">${days.map((day,i)=>{
  const date=addCalendarDays(weekStart,i),daily=items.filter(x=>x.on_date===date),today=date===dateNow();
  return `<section class="schedule-day ${today?'is-today':''}" aria-label="วัน${day} ${esc(thaiScheduleDate(date))}"><div class="schedule-day-head"><span>${day}</span><strong>${esc(thaiScheduleDate(date,{day:'numeric'}))}</strong></div><div class="schedule-day-body">${daily.map(x=>`<article class="schedule-event ${x.source==='makeup'?'makeup':x.group_id?'group':'private'}"><div class="schedule-event-time">${esc(x.start_time)}–${esc(x.end_time)}</div><div class="schedule-event-title">${esc(label(x))}</div><div class="schedule-event-desc">${x.group_id?'กลุ่ม':'เดี่ยว'} · ${esc(nice(duration(x.start_time,x.end_time)))}</div><div class="schedule-event-desc">${esc(x.tutor||'—')}</div>${x.notes?`<div class="schedule-event-note">${esc(x.notes)}</div>`:''}<div class="schedule-event-actions">${btnInline('เปิดคาบ','calendar-drawer',(x.source==='recorded'?'recorded':x.source==='makeup'?'makeup':'planned')+'|'+x.id+'|'+x.on_date)} ${x.source==='recorded'?btnInline('ดูบันทึก','session-detail',x.id):x.source==='makeup'?btnInline('บันทึกชดเชย','record-makeup',x.id):btnInline('แก้ไข','edit-schedule',x.id)+' '+btnInline('ปรับเฉพาะวัน','schedule-exception',x.id+'|'+x.on_date)}</div></article>`).join('')||'<div class="schedule-day-empty">— ไม่มีคาบ —</div>'}</div></section>`;
 }).join('')}</div></div><div class="schedule-mobile-hint">บนมือถือ เลื่อนตารางไปทางซ้าย–ขวาเพื่อดูครบทั้ง 7 วัน</div>`;
 const table=`<div class="table-wrap schedule-table-wrap"><table><thead><tr><th>วันที่</th><th>เวลา</th><th>ประเภท</th><th>นักเรียน / กลุ่ม</th><th>ระยะเวลา</th><th>ติวเตอร์</th><th>ทำซ้ำ</th><th>จัดการ</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(thaiScheduleDate(x.on_date,{weekday:'short',day:'numeric',month:'short'}))}</td><td class="schedule-time-cell">${esc(x.start_time)}–${esc(x.end_time)}</td><td>${pill(x.group_id?'กลุ่ม':'เดี่ยว',x.group_id?'blue':'green')}</td><td><strong>${esc(label(x))}</strong>${x.notes?`<div class="td-secondary">${esc(x.notes)}</div>`:''}</td><td>${esc(nice(duration(x.start_time,x.end_time)))}</td><td>${esc(x.tutor||'—')}</td><td>${pill(x.repeat_rule==='weekly'?'ทุกสัปดาห์':'ครั้งเดียว')}</td><td>${x.source==='recorded'?btnInline('ดูบันทึก','session-detail',x.id):x.source==='makeup'?btnInline('บันทึกชดเชย','record-makeup',x.id):btnInline('แก้ไข','edit-schedule',x.id)+' '+btnInline('ปรับเฉพาะวัน','schedule-exception',x.id+'|'+x.on_date)+' '+btnInline('ยกเลิก','cancel-schedule',x.id)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">ยังไม่มีคาบเรียนในสัปดาห์นี้ ลองเปลี่ยนสัปดาห์หรือกดเพิ่มตารางเรียน</td></tr>'}</tbody></table></div>`;
 return `${head('CALENDAR / PLANNING','Class Schedule','ดูตารางเรียนแบบรายสัปดาห์หรือแบบตารางรายการได้ และสลับมุมมองได้ทุกเวลา',`<div class="button-row">${btn('＋ เพิ่มตารางเรียน','add-schedule','primary')}${btn('Export .ics','export-ics','soft')}${btn('วันลา / ชดเชย','go-leave','soft')}</div>`)}<div class="panel"><div class="note">แสดงทั้งวันเรียนที่วางแผนและคาบที่บันทึกแล้ว · การบันทึกจาก Record Hours / Excel จะปรากฏในปฏิทินและหักชั่วโมงทันที</div>${controls}${stats}${isTable?table:week}</div>`;
}
function openSchedule(s,studentId=''){modal(s?'แก้ไขตารางเรียน':'เพิ่มตารางเรียน',`<form class="form" id="schedule-form"><input type="hidden" name="id" value="${esc(s?.id||'')}">${field('sched-date','วันที่เริ่ม','date',s?.date||dateNow(),'required')}<div class="grid-2">${field('sched-start','เวลาเริ่ม','time',s?.start_time||'18:00','required')}${field('sched-end','เวลาสิ้นสุด','time',s?.end_time||'20:00','required')}</div>${selectField('sched-student','นักเรียนรายบุคคล',studentOptions(s?.student_id||studentId))}${selectField('sched-group','หรือเลือกกลุ่มเรียน',`<option value="">— ไม่ใช่กลุ่ม —</option>${all('Groups').map(g=>`<option value="${esc(g.id)}" ${s?.group_id===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}`)}<div class="grid-2">${field('sched-tutor','ติวเตอร์','text',s?.tutor||'Suthawarin','required')}${selectField('sched-repeat','ทำซ้ำ',`<option value="once" ${s?.repeat_rule!=='weekly'?'selected':''}>เฉพาะครั้งนี้</option><option value="weekly" ${s?.repeat_rule==='weekly'?'selected':''}>ทุกสัปดาห์</option>`)}</div>${field('sched-note','หมายเหตุ','text',s?.notes||'')}<button class="btn primary" type="submit">บันทึกตารางเรียน</button></form>`);}
async function saveSchedule(f){const id=inputVal(f,'id'),date=inputVal(f,'sched-date'),start=inputVal(f,'sched-start'),end=inputVal(f,'sched-end'),studentId=inputVal(f,'sched-student'),groupId=inputVal(f,'sched-group');if(!dateValid(date)||!Number.isFinite(duration(start,end))||duration(start,end)<=0||duration(start,end)>720||(!studentId&&!groupId))throw Error('กรุณาระบุวันที่ เวลา และนักเรียนหรือกลุ่มที่ต้องการสอน');const item={id:id||uuid(),date,student_id:groupId?'':studentId,group_id:groupId,start_time:start,end_time:end,tutor:inputVal(f,'sched-tutor'),repeat_rule:inputVal(f,'sched-repeat'),status:'active',notes:inputVal(f,'sched-note'),created_at:byId('Schedules',id)?.created_at||now()};const change=id?{update:{Schedules:[item]},add:{Audit:[saveAudit('schedule_updated',item.id,{date})]}}:{add:{Schedules:[item],Audit:[saveAudit('schedule_created',item.id,{date})]}};await commit(change);closeModal();toast('บันทึกตารางเรียนแล้ว');}
async function cancelSchedule(id){const s=byId('Schedules',id);if(!s)return;if(!confirm('ยกเลิกตารางเรียนนี้ (รวมรายการทำซ้ำถ้ามี) ใช่หรือไม่?'))return;await commit({update:{Schedules:[{...s,status:'cancelled'}]},add:{Audit:[saveAudit('schedule_cancelled',id,{date:s.date})]}});toast('ยกเลิกตารางเรียนแล้ว');}
function openAdjustment(c){if(!c||!['active','held'].includes(c.status))return;modal('ปรับยอดชั่วโมงคอร์ส',`<form class="form" id="adjust-form"><input type="hidden" name="course_id" value="${esc(c.id)}"><div class="note">${esc(studentName(c.student_id))} · ${esc(c.title)} · คงเหลือ ${fmt(balance(c.id))} ชั่วโมง<br>ใช้ตัวเลขบวกเพื่อเพิ่มชั่วโมง หรือใส่ค่าติดลบเพื่อลดชั่วโมง โดยต้องระบุเหตุผลเพื่อเก็บประวัติ</div>${field('adjust-minutes','นาทีที่ต้องการปรับ (เช่น +30 หรือ -15)','number','30','step="1" min="-10000" max="10000" required')}${field('adjust-reason','เหตุผลในการปรับยอด','text','','required')}<button class="btn primary" type="submit">บันทึกรายการปรับยอด</button></form>`);}
async function saveAdjustment(f){const c=byId('Courses',inputVal(f,'course_id')),minutes=Number(inputVal(f,'adjust-minutes')),reason=inputVal(f,'adjust-reason');if(!c||!['active','held'].includes(c.status)||!Number.isInteger(minutes)||minutes===0||Math.abs(minutes)>10000||!reason)throw Error('รายการปรับยอดไม่ถูกต้อง');if(balance(c.id)+minutes<0)throw Error('ไม่สามารถปรับยอดให้ติดลบ');await commit({add:{Ledger:[{id:uuid(),student_id:c.student_id,course_id:c.id,session_id:'',type:'adjustment',minutes,note:reason,created_at:now()}],Audit:[saveAudit('manual_adjustment',c.id,{minutes,reason})]}});closeModal();toast('ปรับยอดเรียบร้อยพร้อมบันทึกประวัติ');}

function reportClockRaw(d){const clone={...d,timeOverrideStart:'',timeOverrideEnd:''};return reportClock(clone);}

// v2.4 — Operations review tools. All analytics are read-only unless a user confirms
// an existing attendance/payment workflow; browser checks are not server locks.
function importIntelligentWarnings(d){
  if(!d)return '';
  const seen=new Map(),issues=[];
  d.people.forEach((p,i)=>{if(i===d.tutorIndex||!p.include)return;
    if(p.studentId){if(seen.has(p.studentId))issues.push('ชื่อ Meet หลายรายการผูกกับ '+studentName(p.studentId)+' — ตรวจสอบก่อนบันทึก');seen.set(p.studentId,true);}
    const conflict=p.studentId&&duplicateAttendance(d.date,p.studentId,p.join,p.leave);
    if(conflict)issues.push(studentName(p.studentId)+' มีคาบเวลาใกล้เคียงหรือทับซ้อนอยู่แล้วใน '+d.date);
    if(!p.studentId)issues.push('ยังไม่ได้จับคู่ '+p.name);
    if((p.segments||[]).length>1)issues.push(p.name+' เข้า–ออก Meet '+p.segments.length+' ช่วง (เวลาถูกนับแบบไม่ซ้ำช่วง)');
  });
  if(d.timeOverrideStart)issues.unshift('เวลาเรียนถูกปรับโดยผู้ใช้เป็น '+d.timeOverrideStart+'–'+d.timeOverrideEnd+' · เวลาเข้าร่วมจริงในไฟล์ไม่ถูกแก้');
  return `<section class="import-smart-alert" aria-label="Smart Import Pro"><div class="panel-head"><strong>Smart Import Pro · ตรวจความผิดปกติ</strong>${pill(issues.length+' จุดที่ควรตรวจ',issues.length?'gold':'green')}</div>${issues.slice(0,6).map(x=>`<div class="helper">• ${esc(x)}</div>`).join('')||'<div class="helper">ไม่พบข้อควรระวังจากกฎตรวจสอบเบื้องต้น</div>'}<p class="helper">การแก้วัน/เวลาและการจับคู่ชื่อต้องตรวจ Final Review ก่อนบันทึก ทุกไฟล์แยกข้อมูลของตนเอง</p></section>`;
}
function reconciliationOccurrences(from,to){
 const result=[];
 for(const sc of all('Schedules').filter(s=>s.status==='active'&&dateValid(s.date)&&s.date<=to)){
  if(sc.repeat_rule==='weekly'){
   const dayOfWeek=new Date(sc.date+'T12:00:00Z').getUTCDay();
   for(let day=from;day<=to;day=addCalendarDays(day,1))if(day>=sc.date&&new Date(day+'T12:00:00Z').getUTCDay()===dayOfWeek)result.push({...sc,on_date:day});
  }else if(sc.date>=from)result.push({...sc,on_date:sc.date});
 }
 // Keep the original appointment visible as excused and add the replacement
 // separately. For recurring classes these changes affect only one occurrence.
 for(const ex of all('ScheduleExceptions').filter(e=>e.kind==='rescheduled'&&dateValid(e.replacement_date)&&e.replacement_date>=from&&e.replacement_date<=to)){
  const sc=byId('Schedules',ex.schedule_id);if(!sc||sc.status!=='active')continue;
  if(ex.student_id){result.push({...sc,student_id:ex.student_id,group_id:'',on_date:ex.replacement_date,origin_date:ex.occurrence_date,start_time:ex.start_time||sc.start_time,end_time:ex.end_time||sc.end_time,is_replacement:true});}
  else result.push({...sc,on_date:ex.replacement_date,origin_date:ex.occurrence_date,start_time:ex.start_time||sc.start_time,end_time:ex.end_time||sc.end_time,is_replacement:true});
 }
 return result;
}
function reconciliationRows(month,filterStudent=''){
  if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return [];
  const start=month+'-01',end=addCalendarDays(monthOffset(month,1)+'-01',-1),nowDate=dateNow(),out=[];
  for(const sc of reconciliationOccurrences(start,end)){
    const ids=sc.group_id?membersOf(sc.group_id):[sc.student_id].filter(Boolean);
    for(const studentId of ids){if(filterStudent&&studentId!==filterStudent)continue;
      const day=sc.on_date;
      const ex=sc.is_replacement?null:scheduleException(sc.id,sc.origin_date||day,studentId);
      if(sc.is_original_rescheduled||activeLeave(studentId,day)||ex?.kind==='cancelled'||(ex?.kind==='rescheduled'&&!sc.is_replacement)||ex?.kind==='skipped'){
        out.push({sc,studentId,day,status:'excused',reason:ex?.kind==='rescheduled'||sc.is_original_rescheduled?'เลื่อนคาบไปวันใหม่':'ลาหยุด / งดคาบ'});continue;
      }
      const scheduledStart=minutesOf(sc.start_time),scheduledEnd=scheduledStart+duration(sc.start_time,sc.end_time);
      const sameDate=all('Attendance').filter(a=>a.student_id===studentId&&a.status==='approved').map(a=>({a,s:byId('Sessions',a.session_id)})).filter(({s})=>s?.date===day&&s.status==='approved');
      const actual=sameDate.find(({s})=>{
        if(!s||s.status!=='approved'||s.date!==day)return false;
        if(sc.group_id&&s.group_id&&sc.group_id!==s.group_id)return false;
        const startTime=minutesOf(s.start_time),endTime=startTime+duration(s.start_time,s.end_time);
        return Number.isFinite(startTime)&&Math.max(scheduledStart,startTime)<Math.min(scheduledEnd,endTime);
      });
      const isReview=!actual&&sameDate.length>0&&day<=nowDate;out.push({sc,studentId,day,status:actual?'recorded':day>nowDate?'upcoming':isReview?'review':'missing',reason:actual?'บันทึกคาบแล้ว':day>nowDate?'รอถึงวันเรียน':isReview?'พบคาบในวันเดียวกัน แต่เวลาไม่ตรง · ต้องตรวจเอง':'ยังไม่พบ Attendance ที่ตรงกับวันและเวลา',actual:actual?.a});
    }
  }
  return out.sort((a,b)=>a.day.localeCompare(b.day)||a.sc.start_time.localeCompare(b.sc.start_time)||studentName(a.studentId).localeCompare(studentName(b.studentId),'th'));
}
