function receiptHtml(payment){const b=byId('Billing',payment.billing_id);if(!b)throw Error('ไม่พบค่าคาบของใบรับเงิน');const session=byId('Sessions',b.session_id);const student=byId('Students',b.student_id);const fullName=student?.full_name||student?.name||'—';return `<section class="v24-receipt"><div class="v24-receipt-head"><div><div class="receipt-brand">AREWARIN TUTOR</div><h1>ใบรับเงิน / PAYMENT RECEIPT</h1><p>เอกสารยืนยันการรับเงินจริงจากระบบ · ไม่ใช่ใบกำกับภาษี</p></div><div class="receipt-status">PAID</div></div><div class="receipt-grid"><div><small>เลขที่เอกสาร</small><strong>${esc(payment.id)}</strong></div><div><small>วันที่รับชำระ</small><strong>${esc(displayReportDate(payment.paid_on))}</strong></div><div><small>นักเรียน</small><strong>${esc(fullName)}</strong></div><div><small>คอร์ส</small><strong>${esc(courseTitle(b.course_id))}</strong></div></div><table><thead><tr><th>รายละเอียด</th><th>วันเรียน</th><th>จำนวนเวลา</th><th>ยอดรับครั้งนี้</th></tr></thead><tbody><tr><td>ค่าบริการสอนรายชั่วโมง</td><td>${esc(displayReportDate(session?.date))}</td><td>${esc(nice(b.minutes))}</td><td>${baht(payment.amount_satang)}</td></tr></tbody></table><div class="receipt-total"><span>ยอดชำระที่ได้รับจริง</span><strong>${baht(payment.amount_satang)}</strong></div><p>ชำระโดย ${esc(payment.method||'—')} · อ้างอิง: ${esc(payment.note||'—')}</p><p class="receipt-foot">เอกสารอ้างอิงรายการรับชำระรายครั้ง ระบบอาจมีการชำระบางส่วน โปรดดู Payment Center สำหรับยอดคงค้างปัจจุบัน</p></section>`;}
async function receiptPdf(id){const payment=byId('Payments',id);if(!payment)throw Error('ไม่พบการรับเงินจริงที่เลือก · รายการเก่าซึ่งไม่ได้บันทึกใน Payments ยังออกใบรับเงินรายครั้งไม่ได้');
 const html=receiptHtml(payment),name='AreWarin-Receipt-'+payment.id.slice(0,12)+'.pdf';
 if(window.html2canvas&&window.jspdf?.jsPDF){const holder=document.createElement('div');holder.className='v24-pdf-canvas';holder.innerHTML=html;document.body.appendChild(holder);
 try{await document.fonts?.ready;const canvas=await window.html2canvas(holder,{scale:2,backgroundColor:'#ffffff',useCORS:false});const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});const h=canvas.height/canvas.width*190;if(h>277)throw Error('ใบรับเงินยาวเกิน 1 หน้า');pdf.addImage(canvas.toDataURL('image/png'),'PNG',10,10,190,h);pdf.save(name);toast('สร้างใบรับเงิน PDF แล้ว');return;}finally{holder.remove();}}
 const win=window.open('','_blank');if(!win)throw Error('โหลดตัวสร้าง PDF ไม่ได้และป๊อปอัปถูกบล็อก · อนุญาต Pop-up แล้วลองอีกครั้ง');win.document.write(`<!DOCTYPE html><html lang="th"><head><meta charset="utf-8"><title>ใบรับเงิน ${esc(payment.id)}</title><style>body{font-family:Arial,sans-serif;color:#203b31;padding:28px}.v24-receipt{max-width:850px;margin:auto}.v24-receipt-head,.receipt-total{display:flex;justify-content:space-between;align-items:center}.receipt-brand{letter-spacing:3px;font-weight:700;color:#215942}.receipt-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:20px;background:#f4f8f4}small,small+strong{display:block}table{border-collapse:collapse;width:100%;margin-top:25px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.receipt-total{margin:24px 0;font-size:20px}.receipt-foot{color:#65766b}@media print{button{display:none}}</style></head><body>${html}<button onclick="print()">พิมพ์ / Save as PDF</button></body></html>`);win.document.close();}
