function reliabilityIssues(){const issues=[];
 for(const b of all('Billing')){const sum=all('Payments').filter(p=>p.billing_id===b.id).reduce((n,p)=>n+Number(p.amount_satang||0),0);if(sum>Number(b.amount_satang||0))issues.push('ยอดเงินรับเกินใบค่าคาบ: '+b.id.slice(0,8));if(['paid','unpaid','partial'].includes(b.status)&&((sum>=Number(b.amount_satang))!==(b.status==='paid')))issues.push('สถานะชำระไม่ตรงกับยอดรับเงินจริง: '+b.id.slice(0,8));if(!byId('Attendance',b.attendance_id))issues.push('ค่าคาบไม่มี Attendance: '+b.id.slice(0,8));}
 for(const p of all('Payments'))if(!byId('Billing',p.billing_id))issues.push('เงินที่รับไม่พบค่าคาบต้นทาง: '+p.id.slice(0,8));
 for(const a of all('Attendance')){if(!byId('Sessions',a.session_id))issues.push('Attendance ไม่มี Session: '+a.id.slice(0,8));if(!byId('Courses',a.course_id))issues.push('Attendance ไม่มีคอร์ส: '+a.id.slice(0,8));}
 for(const l of all('Ledger'))if(l.course_id&&!byId('Courses',l.course_id))issues.push('Ledger อ้างถึงคอร์สที่ไม่มีอยู่: '+l.id.slice(0,8));
 return issues;
}
function reliabilityExtras(){const issues=reliabilityIssues();return `<section class="panel mt20"><div class="panel-head"><div><h2 class="panel-title">Advanced Reliability · ตรวจยอดและรายการอ้างอิง</h2><p class="panel-desc">ตรวจสถานะรับชำระกับ Payments และความสัมพันธ์ Attendance / Sessions / Courses / Ledger</p></div>${pill(issues.length+' รายการ',issues.length?'gold':'green')}</div>${issues.slice(0,15).map(s=>`<div class="note warn mt12">${esc(s)}</div>`).join('')||'<div class="note">ไม่พบข้อผิดปกติตามกฎเพิ่มเติมที่ตรวจสอบ</div>'}<div class="button-row mt20">${btn('ดาวน์โหลด Audit CSV','audit-json','soft')}<button class="btn soft" data-action="backup-preview">ตรวจไฟล์สำรองก่อนกู้คืน</button><input id="system-verify-file" type="file" accept=".json,application/json" hidden></div><p class="helper mt12">ห้ามกู้คืนทับ Google Sheets จริงจากเบราว์เซอร์โดยตรง · ใช้สำเนา Google Sheets จาก Drive Backup และตรวจข้อมูลก่อนเปลี่ยน Spreadsheet ID</p></section>`;}
function auditExport(){csvFile('AreWarin-Audit-'+dateNow()+'.csv',[['เวลา','เหตุการณ์','รหัสเป้าหมาย','ข้อมูลประกอบ'],...all('Audit').map(a=>[a.created_at,a.action,a.target_id,a.details])]);toast('ดาวน์โหลดประวัติ Audit แล้ว');}
async function previewBackupFile(file){if(!file)return;if(file.size>15*1024*1024)throw Error('ไฟล์ใหญ่เกิน 15 MB');const raw=JSON.parse(await file.text());if(!['AreWarin-TutorOS-backup-v2.3','AreWarin-TutorOS-backup-v2.4'].includes(raw?.format)||!raw.sheets)throw Error('ไม่ใช่ไฟล์สำรอง AreWarin Tutor OS ที่รองรับ');
 const sheetInfo=Object.keys(SCHEMA).map(key=>{const rows=raw.sheets[key];if(!Array.isArray(rows))throw Error('ไฟล์ขาดชีต '+key);const ids=new Set();for(const it of rows){if(!it?.id||ids.has(it.id))throw Error('พบ ID ว่างหรือซ้ำใน '+key);ids.add(it.id);}return [key,rows.length];});
 modal('ตรวจไฟล์สำรอง · Read Only',`<div class="note">บันทึกเมื่อ ${esc(raw.created_at||'ไม่ทราบ')} · รูปแบบ ${esc(raw.format)} · ตรวจแล้ว ${sheetInfo.length} ชีต</div><div class="table-wrap mt20"><table><thead><tr><th>ชีต</th><th>จำนวนแถว</th></tr></thead><tbody>${sheetInfo.map(([name,len])=>`<tr><td>${esc(name)}</td><td>${len}</td></tr>`).join('')}</tbody></table></div><div class="note warn mt12">การตรวจเบื้องต้นนี้ไม่ได้พิสูจน์ความครบถ้วนของความสัมพันธ์ข้อมูลและไม่เขียนข้อมูลใด ๆ กลับฐานข้อมูลจริง · หากกู้คืน ให้ตรวจสำเนา Google Sheets แยกก่อน</div>`,btn('ปิด','close-modal'),true);
}
